  '\\nWeekly email health and form activity report\\n' => 'Haftalık e-posta sağlık ve form etkinliği raporu',
  '\\nAdds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.\\n' => 'Form etkinliği toplamlarınızı &ndash; formlar, görüntülemeler ve gönderimler &ndash; sitenizin ana yöneticiye gönderdiği haftalık e-postaya ekler. Bu toplamlar kendi sitenizde okunur ve asla WhiteStudio\'ya gönderilmez.',
  'Last check: %s' => 'Son kontrol: %s',
  '\\nNo automated email check has run yet.\\n' => 'Henüz otomatik e-posta kontrolü çalıştırılmadı.',
  '\\nCollect email delivery statistics\\n' => 'E-posta teslim istatistiklerini topla',
  '\\nCounts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.\\n' => 'Kaç e-postanın gönderildiğini veya başarısız olduğunu sayar, bunları dashboard widget\'ında gösterir ve haftalık e-postaya e-posta teslim durumu bölümünü ekler. Sitenizde haftada bir teslim testi çalıştırılır ve sonuç raporlanır. Bunu yalnızca Pro kullanıcıları kapatabilir.',
