  '\\nUploaded File\\n' => 'Yüklenen Dosya',
  '\\nYour internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.\\n' => 'İnternet bağlantınız kesildi ancak endişelenmeyin, bu forma girdiğiniz bilgileri kaydettik. İnternete yeniden bağlandığınızda gönder düğmesine tıklayarak bilgilerinizi kolayca gönderebilirsiniz.',
  '\\nPlease ensure that you have a stable internet connection and try again.\\n' => 'Lütfen internet bağlantınızın kararlı olduğundan emin olun ve tekrar deneyin.',
  '\\nThere was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.\\n' => 'Dosya yüklenirken bir sorun oluştu ve form gönderilmedi. Lütfen internet bağlantınızın kararlı olduğunu kontrol edin ve tekrar deneyin.',
  'Options' => 'Seçenekler',
  '\\nYou are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)\\n' => 'jQuery ile ilgili sorun yaşıyorsunuz. Yardım için lütfen yönetici ile iletişime geçin. (Hata kodu: JQ-500)',
