  '\\nPersia payment\\n' => 'Persia ödemesi',
  '[[\'Unlock Pro Features Today\\n' => 'Pro Özelliklerinin Kilidini Bugün Açın',
  '\\nUpgrade to Pro for just%1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s\\n' => 'Yılda yalnızca %1$s %2$s%3$s karşılığında Pro\'ya yükseltin ve gelişmiş form alanları, ödeme entegrasyonları, koşullu mantık, çok adımlı formlar, dosya yükleme, Güvenlik ve Spam Koruması ile öncelikli destek dahil güçlü özelliklere erişin.%4$sPro Özelliklerini Görüntüle%5$s',
  '\\nAdd-on\\n' => 'Eklenti',
  '\\nAdd-ons\\n' => 'Eklentiler',
  '[[\'Stripe Payment Add-on\\n' => 'Stripe Ödeme Eklentisi',
  '\\nThe Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.\\n' => 'Flux Forms için Stripe eklentisi, WordPress sitenizi ödeme işleme, bağışlar ve çevrimiçi siparişler için Stripe ile entegre etmenizi sağlar.',
  '[[\'Offline Forms Add-on\\n' => 'Çevrimdışı Formlar Eklentisi',
  '\\nThe Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.\\n' => 'Flux Forms için Çevrimdışı Formlar eklentisi, kullanıcıların çevrimdışı durumlarda formları doldururken ilerlemelerini kaydetmelerine olanak tanır.',
  'Install' => 'Yükle',
  '[["Please update Flux Forms before trying again.\\n' => 'Lütfen tekrar denemeden önce Flux Forms\'u güncelleyin.',
  '\\nActivation of offline form mode.\\n' => 'Çevrimdışı form modunun etkinleştirilmesi.',
  '\\nBefore activating this option, install\\n' => 'Bu seçeneği etkinleştirmeden önce şunu yükleyin:',
  '\\nTo create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.\\n' => 'Çevrimiçi ödeme toplamak için bir ödeme formu oluşturmak üzere önce Stripe Eklentisi gibi bir ödeme eklentisi yüklemelisiniz.',
  '\\nAll formats\\n' => 'Tüm biçimler',
  '\\nEFB SMS Add-on\\n' => 'EFB SMS Eklentisi',
  '\\nEnable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.\\n' => 'EFB SMS eklentisiyle formlarınızda SMS özelliğini etkinleştirin; cep telefonu numaralarını doğrulayın, SMS ile onay kodları gönderin ve SMS hizmeti üzerinden bildirim alın.',
  '\\nAdvanced confirmation code Add-on\\n' => 'Gelişmiş onay kodu Eklentisi',
  '\\nSend a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.\\n' => 'Kullanıcılara ve/veya yöneticilere e-posta veya SMS ile onay kodu göndererek yeni yanıtlara hızlıca erişmelerini sağlayın.',
  '\\nBox Checklist\\n' => 'Kutu Kontrol Listesi',
