  'warning' => 'uyarı',
  '\\ndate & time\\n' => 'tarih ve saat',
  '\\nEnable file upload in the response box\\n' => 'Yanıt kutusunda dosya yüklemeyi etkinleştir',
  '\\nEnable Google reCAPTCHA in the response box\\n' => 'Yanıt kutusunda Google reCAPTCHA\'yı etkinleştir',
