  '\\nPersia Payment Add-on\\n' => 'Persia Ödeme Eklentisi',
  '\\nThe Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.\\n' => 'Flux Forms için Persia ödeme eklentisi, web sitenizi Persia ödeme ile bağlayarak ödemeleri, bağışları ve çevrimiçi siparişleri işlemenizi sağlar.',
  '\\nJalali Date Add-on\\n' => 'Celali Tarih Eklentisi',
  '\\nThe Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.\\n' => 'Celali Tarih eklentisi, formlarınıza Celali tarih alanı eklemenizi ve bu Şemsi tarih alanını içeren her türlü formu oluşturmanızı sağlar.',
  '\\nHijri Date Add-on\\n' => 'Hicri Tarih Eklentisi',
  '\\nThe Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.\\n' => 'Hicri Tarih eklentisi, formlarınıza Hicri tarih alanı eklemenizi ve bu alanı içeren her türlü formu oluşturmanızı sağlar.',
  '\\nSMS service Add-on\\n' => 'SMS hizmeti Eklentisi',
  '\\nThe SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.\\n' => 'SMS hizmeti eklentisi, siz veya müşterileriniz yeni mesaj ya da yanıt aldığında bildirim SMS\'leri almanızı sağlar.',
  '\\nPlease install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.\\n' => 'Lütfen Hicri veya Celali tarih eklentilerinden yalnızca birini yükleyin. İki eklentiyi aynı anda yükleyemezsiniz.',
  '\\nResponse box\\n' => 'Yanıt kutusu',
  '\\nRegions Drop-Down\\n' => 'Bölgeler Açılır Listesi',
  '\\nYou are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.\\n' => 'Bu mesajı, gerekli eklentileriniz yüklendiği için görüyorsunuz. Lütfen birkaç dakika bekleyip bu sayfayı yeniden ziyaret edin. Beş dakikadan uzun süre geçtiyse ve bir şey olmadıysa, lütfen Whitestudio.team adresindeki Flux Forms destek ekibiyle iletişime geçin.',
  '\\nThe cell phone number is incorrect\\n' => 'Cep telefonu numarası hatalı',
  '\\nInvalid country code\\n' => 'Geçersiz ülke kodu',
  '\\nThe cell phone number is too short\\n' => 'Cep telefonu numarası çok kısa',
  '\\nThe cell phone number is too long\\n' => 'Cep telefonu numarası çok uzun',
  '\\nPlease select the number of countries to display within an acceptable range.\\n' => 'Lütfen görüntülenecek ülke sayısını kabul edilebilir bir aralıkta seçin.',
  '\\nDisabled Field\\n' => 'Devre Dışı Alan',
  '\\nHidden Field\\n' => 'Gizli Alan',
  '[[\'Select a country to display a list of states/provinces.\\n' => 'Eyalet/il listesini görüntülemek için bir ülke seçin.',
  '\\nSelect a state/province to display a list of cities.\\n' => 'Şehir listesini görüntülemek için bir eyalet/il seçin.',
  '\\nSMS Service Add-on\\n' => 'SMS Hizmeti Eklentisi',
  '[["This field is currently unavailable. Please contact the site administrator.\\n' => 'Bu alan şu anda kullanılamıyor. Lütfen site yöneticisiyle iletişime geçin.',
  '\\nWould you like to customize the form using the colors of the active template?\\n' => 'Formu etkin şablonun renklerini kullanarak özelleştirmek ister misiniz?',
  '\\nFlux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.\', \'en\']]' => 'Flux Forms etkin şablonun renklerini kullandı. Oluşturduğunuz formu şablonunuzun renklerine göre özelleştirmek için lütfen aşağıdaki her seçenek için bir renk seçin. Her seçenek için bir renk seçtiğinizde, o özellikle ilişkili tüm form alanlarının rengi buna göre değişir.',
  '\\nButtons text colors\\n' => 'Düğme metin renkleri',
