  '\\nConditional logic Add-on\\n' => 'Koşullu mantık Eklentisi',
  '\\nThe Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.\\n' => 'Koşullu Mantık Eklentisi, belirli kullanıcı girdilerine veya koşullu kurallara dayalı dinamik ve etkileşimli formlar oluşturmanızı sağlar. Kullanıcıların kendine özgü ihtiyaçlarına uygun, yüksek düzeyde kişiselleştirilmiş formlara olanak tanır.',
  '\\nThe Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.\\n' => 'Koşullu Mantık modülü yüklenemedi. Lütfen sayfayı yenileyin; sorun devam ederse Koşullu Mantık eklentisini devre dışı bırakıp yeniden etkinleştirin.',
