  '\\nError: Please ensure there is only one form per page.\\n' => 'Hata: Lütfen sayfa başına yalnızca bir form olduğundan emin olun.',
  '\\nYour activation code has been verified. Enjoy all Pro features of Flux Forms.", \'en\']]' => 'Etkinleştirme kodunuz doğrulandı. Flux Forms\'un tüm Pro özelliklerinin keyfini çıkarın.',
  '\\nThe confirmation code for this message is%s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.\\n' => 'Bu mesajın onay kodu %s. Aşağıdaki düğmeye tıklayarak mesajları takip edebilir ve alınan yanıtları görüntüleyebilirsiniz. Gerekirse yeni bir yanıt da gönderebilirsiniz.',
  '\\nTo explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our%1$sdocumentation%2$s.\\n' => 'E-posta yapılandırmaları, form oluşturma seçenekleri ve diğer özellikler dahil Flux Forms\'un tüm işlevlerini ve ayarlarını keşfetmek için %1$s dokümantasyonumuza %2$s göz atmanız yeterli.',
  '\\nResponses & Confirmation\\n' => 'Yanıtlar ve Onay',
  '\\nTest emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings%1$sLearn how to fix email delivery issues%2$sor%3$scontact Flux Forms support%4$s.\\n' => 'Test e-postaları spam klasörünüze düşebilir. E-postalar iletilmiyorsa bu genellikle barındırma veya e-posta sunucusu yapılandırmanızla ilgilidir. sunucu ayarları %1$sE-posta teslim sorunlarını nasıl çözeceğinizi öğrenin%2$s veya %3$sYT Form desteğiyle iletişime geçin%4$s.',
  '\\nFrom Address\\n' => 'Gönderen Adresi',
  '\\nMake sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.\\n' => 'E-posta teslim sorunlarını önlemek için bu e-posta adresinin SMTP ayarlarınızda yapılandırılan adresle eşleştiğinden emin olun.',
  '\\nTo preview the form, you need to save the built form and try again.\\n' => 'Formu önizlemek için oluşturduğunuz formu kaydetmeniz ve tekrar denemeniz gerekir.',
  '\\nNo selected rows found.\\n' => 'Seçili satır bulunamadı.',
  '\\nMark as Read\\n' => 'Okundu olarak işaretle',
  '\\nRequire admin login to view responses\\n' => 'Yanıtları görüntülemek için yönetici girişi iste',
  '\\nDevelopment Mode (Sandbox)\\n' => 'Geliştirme Modu (Sandbox)',
  '\\nWhen enabled, uses sandbox/demo servers for PayPal and other services. Disable for production.\\n' => 'Etkinleştirildiğinde PayPal ve diğer hizmetler için sandbox/demo sunucuları kullanılır. Canlı ortam için devre dışı bırakın.',
  '\\nAfter changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.\\n' => 'Geliştirme Modu (Sandbox) seçeneğini değiştirdikten sonra ayarları kaydedin, ardından değişikliklerin geçerli olması için Flux Forms eklentisini Eklentiler sayfasından devre dışı bırakıp yeniden etkinleştirin.',
  '\\nI have read and agree to%1$sthe terms and conditions%2$s\\n' => '%1$sŞartlar ve koşulları%2$s okudum ve kabul ediyorum',
  '\\nTerms\\n' => 'Koşullar',
