  '\\nEnable Location Picker in Flux Forms\\n' => 'Flux Forms\'da Konum Seçici\'yi etkinleştir',
  '\\nFlux Forms cannot display the form because jQuery is not properly loaded. This issue might be due to incorrect jQuery invocation by another plugin or the current website theme.\\n' => 'jQuery düzgün yüklenmediği için Flux Forms formu görüntüleyemiyor. Bu sorun, başka bir eklentinin veya mevcut web sitesi temasının jQuery\'yi yanlış çağırmasından kaynaklanıyor olabilir.',
  '\\nTelegram Notification Add-on\\n' => 'Telegram Bildirim Eklentisi',
