  '\\nThe form cannot be submitted because it requires a payment method, which is currently missing. If you are the Admin, please add a payment method to the form or change the form type to "Form" or "Survey".\\n' => 'Form, şu anda eksik olan bir ödeme yöntemi gerektirdiği için gönderilemiyor. Yöneticiyseniz lütfen forma bir ödeme yöntemi ekleyin veya form türünü "Form" ya da "Anket" olarak değiştirin.',
  'Payments' => 'Ödemeler',
  '\\nCache Plugin Detected\\n' => 'Önbellek Eklentisi Algılandı',
  '\\nThe following cache plugins may interfere with form functionality. If you experience issues, please review the documentation.\\n' => 'Aşağıdaki önbellek eklentileri form işleyişini etkileyebilir. Sorun yaşarsanız lütfen belgelere göz atın.',
  'Plugin' => 'Eklenti',
  'Version' => 'Sürüm',
