  '\\nDismiss%s\\n' => '%s öğesini kapat',
  '\\nSecurity Plugin Detected\\n' => 'Güvenlik Eklentisi Algılandı',
  '\\nThe following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.\\n' => 'Aşağıdaki güvenlik eklentisi form gönderimlerini 403 hatalarıyla engelleyebilir. REST API\'yi engelleyebilir, X-WP-Nonce başlığını kaldırabilir veya form isteklerine güvenlik duvarı kuralları uygulayabilir.',
  '\\nRead more about security plugin compatibility\\n' => 'Güvenlik eklentisi uyumluluğu hakkında daha fazla bilgi edinin',
  '\\nAuto-Populate Add-on\\n' => 'Otomatik Doldurma Eklentisi',
  '\\nThe Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.\\n' => 'Otomatik Doldurma eklentisi, form alanlarını veri kümelerinden, daha önce gönderilen formlardan veya harici API\'lerden otomatik olarak doldurmanızı sağlar.',
  '\\nForm Security & Spam Protection\\n' => 'Form Güvenliği ve Spam Koruması',
  '\\nBehavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.\\n' => 'Hız sınırları ve SMS, Telegram, e-posta ve webhook gibi ücretli bildirimler için zarar durdurma özelliğiyle davranış tabanlı spam ve API kötüye kullanım koruması.',
  '\\nGoogle Sheet Add-on\\n' => 'Google Sheet Eklentisi',
  '\\nAutomatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.\\n' => 'Form gönderimlerini gerçek zamanlı olarak Google E-Tablolarınıza otomatik gönderin. Bir hizmet hesabı bağlayın, alanları sütunlarla eşleyin ve her yanıtın canlı, biçimlendirilmiş bir e-tablosunu tutun — webhook veya tarayıcı girişi gerekmez.',
  '\\nPlease fill in all required fields\\n' => 'Lütfen tüm zorunlu alanları doldurun',
  '\\nEmail Server Status\\n' => 'E-posta Sunucusu Durumu',
  '\\nThe test email never arrived\\n' => 'Test e-postası ulaşmadı',
  '\\nYour WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.\\n' => 'WordPress siteniz e-postaları güvenilir şekilde gönderemiyor. Bu çok yaygın bir barındırma sorunudur — varsayılan PHP mail işlevi sıklıkla engellenir veya spam\'e düşer. Bir SMTP eklentisi kurmak e-postalarınızı doğrulanmış bir posta hizmeti üzerinden yönlendirir ve bunu dakikalar içinde çözer.',
  '\\nWordPress sent the email - it just never arrived\\n' => 'WordPress e-postayı gönderdi - ancak e-posta hiç ulaşmadı',
  '\\nYour site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.\\n' => 'Siteniz mesajı posta sunucunuza başarıyla teslim etti; yani WordPress ve bu eklenti üzerine düşeni yaptı. Mesaj sonrasında kayboldu, gecikti veya reddedildi - çoğunlukla alıcının posta kutusu onu spam olarak işaretlemiş veya barındırma sağlayıcınız onu giden kuyruktan hiç teslim etmemiştir. Bunu çözen şey, alan adınız için SPF ve DKIM kayıtlarıyla bir SMTP hizmeti üzerinden göndermektir.',
  '\\nWordPress could not send the email\\n' => 'WordPress e-postayı gönderemedi',
  '\\nThe message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.\\n' => 'Mesaj web sitenizden hiç çıkmadı: WordPress gönderirken bir hata döndürdü. Bir SMTP eklentisi kurup yapılandırın veya barındırma sağlayıcınıza PHP mail\'in devre dışı olup olmadığını sorun.',
  '\\nYour emails arrive, but will most likely land in spam\\n' => 'E-postalarınız ulaşıyor ancak büyük olasılıkla spam\'e düşecek',
  '[[\'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.\\n' => 'Teslimatın kendisi çalışıyor - test mesajı bize ulaştı. Eksik olan güven: bir SMTP hizmeti üzerinden göndermek ve alan adınız için SPF ve DKIM kayıtları eklemek, e-postalarınızı spam klasöründen gelen kutusuna taşır.',
  '\\nThe test email was delivered with a deliverability score of%1$sout of 100. Under%2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.\\n' => 'Test e-postası 100 üzerinden %1$s teslim edilebilirlik puanıyla teslim edildi. %2$s altında çoğu posta kutusu mesajları spam klasörüne koyar; bu nedenle formlarınızı dolduran kişiler onları hiç göremeyebilir.',
  '\\nStep-by-step SMTP setup guide\\n' => 'Adım adım SMTP kurulum rehberi',
  '\\nYour email server is working. A detailed HTML report has been sent to%s.\\n' => 'E-posta sunucunuz çalışıyor. Ayrıntılı bir HTML raporu %s adresine gönderildi.',
  '\\nyour admin email address\\n' => 'yönetici e-posta adresiniz',
  '\\nSpam Score Report on the Way!\\n' => 'Spam Puanı Raporu Yolda!',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent to%swithin the next few minutes.\\n' => 'Spam puanınız, teslim edilebilirlik ayrıntıları ve önerileri içeren eksiksiz bir e-posta sağlık raporu önümüzdeki birkaç dakika içinde %s adresine gönderilecek.',
  '\\nEmail notifications may not be delivered\\n' => 'E-posta bildirimleri teslim edilmeyebilir',
  '\\nThis form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is%s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.\\n' => 'Bu formun e-posta bildirimi özelliği etkin ancak e-posta teslimatı doğrulanmadı ve son spam puanı %s/100. Form kaydedildi, ancak SMTP/e-posta teslimatı düzeltilene kadar yönetici bildirim e-postaları size ulaşmayabilir.',
  '\\nNotification emails are turned off\\n' => 'Bildirim e-postaları kapalı',
  '\\nFlux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.\\n' => 'E-posta Ayarları\'nda "Bu site e-posta gönderebilir" etkinleştirilene kadar Flux Forms ne size ne de bu formu gönderen kişiye hiçbir e-posta göndermeyecektir.',
  '[[\'Enable email sending\\n' => 'E-posta göndermeyi etkinleştir',
  '\\nClick "Check Email Server" to test delivery, turn this switch on, then press Save.\\n' => 'Teslimatı test etmek için "E-posta Sunucusunu Kontrol Et"e tıklayın, bu anahtarı açın, ardından Kaydet\'e basın.',
  '\\nDelivery is taking longer than expected\', \'en\']]' => 'Teslimat beklenenden uzun sürüyor',
  '\\nWordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.\\n' => 'WordPress test e-postasını gönderdi ancak sunucumuz henüz almadı. Bu geçici bir gecikme olabilir. Sorunu gidermek için aşağıdaki tanılamaları kontrol edin.',
  '\\nPrepare Test\\n' => 'Testi Hazırla',
  '\\nConnecting to WhiteStudio to generate a unique test email address.\\n' => 'Benzersiz bir test e-posta adresi oluşturmak için WhiteStudio\'ya bağlanılıyor.',
  '\\nWordPress Sends the Email\\n' => 'WordPress E-postayı Gönderir',
  '\\nWordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.\\n' => 'WordPress gerçek bir mesajı posta sunucunuza iletir. Buradaki onay işareti, WordPress\'in gönderdiği anlamına gelir; henüz ulaştığı anlamına gelmez.',
  '\\nWaiting for Delivery\\n' => 'Teslimat Bekleniyor',
  '\\nChecking whether the test email arrived at our server (usually takes a few seconds).\\n' => 'Test e-postasının sunucumuza ulaşıp ulaşmadığı kontrol ediliyor (genellikle birkaç saniye sürer).',
  '\\nQuick Result\\n' => 'Hızlı Sonuç',
  '\\nShowing the first delivery result — you will see right away if email is working.\\n' => 'İlk teslimat sonucu gösteriliyor — e-postanın çalışıp çalışmadığını hemen görürsünüz.',
  '\\nFull Report\\n' => 'Tam Rapor',
  '\\nA detailed HTML report with full diagnostics is being prepared and emailed to you.\\n' => 'Tam tanılama içeren ayrıntılı bir HTML raporu hazırlanıyor ve size e-postayla gönderiliyor.',
