  '\\nThe missing add-on files could not be restored. Check the server connection and file permissions, then try again.\\n' => 'Eksik eklenti dosyaları geri yüklenemedi. Sunucu bağlantısını ve dosya izinlerini kontrol edip tekrar deneyin.',
