  '\\nAutomatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.\\n' => 'Otomatik kurtarma denendi ancak tamamlanamadı. Aşağıdaki nedeni inceleyin, gerekirse düzeltin ve tekrar deneyin.',
