  '\\nWe could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.\\n' => 'Gerekli bir form bileşeni otomatik olarak geri yüklenemedi. Lütfen kısa süre sonra tekrar deneyin; site yöneticisi tam kurtarma hatasını Flux Forms içinde görüntüleyebilir.',
  '\\nThe add-on is already installed.\\n' => 'Eklenti zaten yüklü.',
  '\\nFile access status not checked yet. Please wait.\\n' => 'Dosya erişim durumu henüz kontrol edilmedi. Lütfen bekleyin.',
