  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the%sserver\\n' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti %s sunucusuna bağlanamıyor',
  '\\nYour Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:\\n' => 'Flux Forms Pro aboneliğinizin süresi doldu, bu nedenle Pro eklentileri indirilemedi. Eklenti bunlar olmadan çalışmaya devam eder. Tüm Pro özelliklerini geri yüklemek için aboneliğinizi yenileyin:',
  '\\nThe version of the add-on is not compatible with the version of the Flux Forms plugin.\\n' => 'Eklentinin sürümü Flux Forms eklentisinin sürümüyle uyumlu değil.',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to download files\\n' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti dosyaları indiremiyor',
  '\\nCannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.\\n' => 'Eklentiler kurulamıyor çünkü bu sunucu, indirmeyi hazırlamak için gereken PHP dosya sistemi işlevlerini devre dışı bırakmış. Lütfen barındırma sağlayıcınızdan mkdir ve rename işlevlerini etkinleştirmesini isteyin veya WordPress dosya sistemini yapılandırın.',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file\\n' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti indirilen dosyayı taşıyamıyor',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to unzip files\', \'en\']]' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti zip dosyalarını açamıyor',
  '\\nTo fix this, sign in to your%s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.\\n' => 'Bunu düzeltmek için %s hesabınızda oturum açın, İndirmeler bölümünden Add-ons Handler eklentisini indirin, ardından kurup etkinleştirin. Sonra ihtiyacınız olan eklentileri Add-ons Handler eklentisinden etkinleştirin.',
  '\\nWhiteStudio dashboard\\n' => 'WhiteStudio dashboard',
  '\\nThis bundled add-on is missing from the plugin files.\\n' => 'Bu pakete dahil eklenti, eklenti dosyalarında eksik.',
  '\\nThe add-on server returned an unexpected response.\\n' => 'Eklenti sunucusu beklenmeyen bir yanıt döndürdü.',
  '\\nThe add-on could not be installed.\\n' => 'Eklenti yüklenemedi.',
  '\\nThe add-on server did not provide a download URL.\\n' => 'Eklenti sunucusu bir indirme URL\'si sağlamadı.',
  '\\nThe add-on download URL is not an approved Flux Forms source.\\n' => 'Eklenti indirme URL\'si onaylı bir Flux Forms kaynağı değil.',
  '\\nYour server could not reach%1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at%2$sand download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.\\n' => 'Sunucunuz %1$s adresine ulaşamadığı için eklenti indirilemedi. Bu hemen hemen her zaman lisansınızla ilgili bir sorun değil, barındırmanızdaki bir güvenlik duvarının giden isteği engellemesidir. Eklentileri hiç indirmeden yüklemek için %2$s adresinde oturum açın, Flux Forms Add-ons Handler eklentisini indirin ve diğer eklentiler gibi yükleyin. Lisansınızın kapsadığı tüm eklentileri içerir.',
  '\\nIf you would rather fix the connection, ask your hosting provider why outgoing requests from%sare being blocked.\\n' => 'Bağlantıyı düzeltmeyi tercih ederseniz, barındırma sağlayıcınıza %s adresinden giden isteklerin neden engellendiğini sorun.',
  '\\nFlux Forms: add-on downloads are being blocked\\n' => 'Flux Forms: eklenti indirmeleri engelleniyor',
  '\\nAdd-on affected:%s\\n' => 'Etkilenen eklenti: %s',
  '\\nNo response was recorded for this add-on.\\n' => 'Bu eklenti için kayıtlı bir yanıt yok.',
  '\\nWritable\\n' => 'Yazılabilir',
  '\\nNot writable — the add-on folder cannot be created or extracted into.\\n' => 'Yazılamaz — eklenti klasörü oluşturulamıyor veya içine çıkarma yapılamıyor.',
  '\\nBlocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.\\n' => 'WP_HTTP_BLOCK_EXTERNAL tarafından engellendi — bu sitede giden istekler devre dışı.',
  'Allowed' => 'İzin verildi',
  '\\nDISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.\\n' => 'DISABLE_WP_CRON açık — arka plan yeniden denemeleri yalnızca bir sunucu cron görevi wp-cron.php\'yi çağırırsa çalışır.',
  'Site' => 'Site',
  '\\nPage that needed it\\n' => 'Gerektiren sayfa',
  '\\nPlugin version\\n' => 'Eklenti sürümü',
  'WordPress' => 'WordPress',
  '\\nAdd-on folder\\n' => 'Eklenti klasörü',
  '\\nOutgoing requests\\n' => 'Giden istekler',
  '\\nWP-Cron\\n' => 'WP-Cron',
  '\\nAttempts made\\n' => 'Yapılan deneme sayısı',
  '\\nFlux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.\\n' => 'Flux Forms, eklenti dosyalarını otomatik olarak yeniden yükleyemedi. Bu eklentilere dayanan formlar, sorun çözülene kadar ziyaretçilere geçici bir mesaj gösteriyor.',
  '\\nWhat is missing\\n' => 'Neler eksik',
  '\\nDiagnostics\\n' => 'Tanılama',
  '\\nWhat to do next\\n' => 'Sonraki adım',
  '\\nOpen Flux Forms in your dashboard and use the Recover add-ons button.\\n' => 'Dashboard\'unuzda Flux Forms\'u açın ve Eklentileri kurtar düğmesini kullanın.',
  '\\nIf the add-on folder is not writable, ask your host to allow writing to the plugin folder.\\n' => 'Eklenti klasörü yazılabilir değilse, barındırma sağlayıcınızdan eklenti klasörüne yazmaya izin vermesini isteyin.',
  '\\nIf outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.\\n' => 'Giden istekler engelleniyorsa, barındırma sağlayıcınızdan Flux Forms güncelleme sunucusuna bağlantılara izin vermesini isteyin.',
  '\\nIf your Pro subscription has expired, renew it to restore the Pro add-ons.\\n' => 'Pro aboneliğinizin süresi dolduysa, Pro eklentilerini geri yüklemek için yenileyin.',
  '\\nWe have made some updates. Please wait a few minutes before trying again.\\n' => 'Bazı güncellemeler yaptık. Lütfen tekrar denemeden önce birkaç dakika bekleyin.',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server\\n' => 'Flux Forms eklentileri yüklenemiyor çünkü eklenti whitestudio.team sunucusuna bağlanamıyor',
  '\\nOne of the free features\\n' => 'Ücretsiz özelliklerden biri',
  '\\nImportant: Caching Plugin May Affect Flux Forms\\n' => 'Önemli: Önbellek Eklentisi Flux Forms\'u Etkileyebilir',
  '\\nThe following caching plugins are active on your site:\\n' => 'Sitenizde aşağıdaki önbellek eklentileri etkin:',
  '\\nPlugin Name\\n' => 'Eklenti Adı',
  '\\nSlug\\n' => 'Slug',
  '\\nPlease note that these plugins may affect the functionality of Flux Forms.\\n' => 'Bu eklentilerin Flux Forms\'un işleyişini etkileyebileceğini unutmayın.',
  '\\nIf you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.\\n' => 'Herhangi bir sorun yaşarsanız, formunuzun yayınlandığı sayfayı önbellekten hariç tutun veya bu eklentileri devre dışı bırakın. Bu hariç tutmanın nasıl ayarlanacağına dair ayrıntılı bilgi için ilgili önbellek eklentisinin belgelerine bakın.',
  '\\nSent by\\n' => 'Gönderen',
  '\\nAction needed: Flux Forms Pro is paused on%s\\n' => 'İşlem gerekli: Flux Forms Pro, %s sitesinde duraklatıldı',
  '\\nFlux Forms could not confirm your Pro licence for%1$sdays in a row, so the Pro features on%2$sare paused for now.\\n' => 'Flux Forms, %1$s gün üst üste Pro lisansınızı doğrulayamadı; bu nedenle %2$s sitesindeki Pro özellikleri şimdilik duraklatıldı.',
  '\\nYour forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.\\n' => 'Formlarınıza, girdilerinize ve ayarlarınıza dokunulmadı, tüm ücretsiz özellikler çalışmaya devam ediyor ve etkinleştirme kodunuz hâlâ saklanıyor &mdash; hiçbir şey silinmedi.',
  '\\nOpen%1$sYT Form → Settings%2$sand press%1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.\\n' => '%1$sYT Form &rarr; Ayarlar%2$s sayfasını açın ve %1$sKaydet%2$s düğmesine basın. Bu, lisansı hemen yeniden kontrol eder; bağlantı geri geldiyse Pro bir dakika içinde açılır.',
  '\\nStill paused? Ask your hosting provider to allow outgoing HTTPS connections to%s— a firewall, proxy or regional block is the usual cause — then repeat step 1.\\n' => 'Hâlâ duraklatılmış mı? Barındırma sağlayıcınızdan %s adresine giden HTTPS bağlantılarına izin vermesini isteyin &mdash; genellikle nedeni bir güvenlik duvarı, proxy veya bölgesel engeldir &mdash; ardından 1. adımı tekrarlayın.',
  '\\nIf your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.\', \'en\']]' => 'Aboneliğinizin süresi dolduysa veya bu web sitesini yeni bir alan adına taşıdıysanız, %1$slisansınızı yenileyin veya yeniden etkinleştirin%2$s ve yeni kodu Ayarlar\'a yapıştırın.',
  'Reason' => 'Neden',
  '\\nFirst failed check\\n' => 'İlk başarısız kontrol',
  '\\ngrace period\\n' => 'Ek süre',
  '%s days' => '%s gün',
  '\\nActivation code\\n' => 'Etkinleştirme kodu',
  '\\nError code\\n' => 'Hata kodu',
  '\\nHow to bring Pro back\\n' => 'Pro nasıl geri getirilir',
  '\\nCheck my licence now\\n' => 'Lisansımı şimdi kontrol et',
  '\\nStill stuck? Send the details above to%1$sour support team%2$sand we will take it from there.\\n' => 'Hâlâ çözemediniz mi? Yukarıdaki ayrıntıları %1$sdestek ekibimize%2$s gönderin, gerisini biz hallederiz.',
  '\\nThe licence server answered with an error and could not confirm your licence.\\n' => 'Lisans sunucusu bir hatayla yanıt verdi ve lisansınızı doğrulayamadı.',
  '\\nYour website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.\\n' => 'Web siteniz lisans sunucusuna ulaşamadı &mdash; neredeyse her zaman barındırma tarafındaki bir ağ, güvenlik duvarı veya DNS kısıtlamasıdır.',
  '\\nThe licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.\\n' => 'Lisans sunucusu&rsquo;nun yanıtı bozuk ulaştı; genellikle bir güvenlik eklentisi, proxy veya CDN onu yolda değiştirmiştir.',
  '\\nThe licence check could not be completed.\\n' => 'Lisans kontrolü tamamlanamadı.',
  '[[\'Your activation code has expired!\\n' => 'Etkinleştirme kodunuzun süresi doldu!',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue using the%sadd-on and all Pro features, please renew your subscription.\\n' => 'Flux Forms Pro aboneliğinizin süresi doldu. %s eklentisini ve tüm Pro özelliklerini kullanmaya devam etmek için lütfen aboneliğinizi yenileyin.',
  '\\nRenew Subscription\\n' => 'Aboneliği Yenile',
