  '\\nYour Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running,%1$sRenew your subscription now.%2$s\\n' => 'Flux Forms Pro aboneliğinizin süresi doldu. Tüm Pro özelliklerinin keyfini çıkarmaya devam etmek ve formlarınızı çalışır durumda tutmak için %1$sAboneliğinizi şimdi yenileyin.%2$s',
  '\\nThe payment could not be verified yet.\\n' => 'Ödeme henüz doğrulanamadı.',
