  '\\nPayments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.\\n' => 'Formlarınız üzerinden, tüm ödeme sağlayıcılarıyla alınan ödemeler. API anahtarları ve etkin sağlayıcı eklentinin Ayarlar sayfasındaki Ödemeler sekmesinden belirlenir.',
