  '\\nTest provider (development only)\\n' => 'Test sağlayıcısı (yalnızca geliştirme)',
  '[[\'Test outcome\\n' => 'Test sonucu',
  '\\nApprove every payment\\n' => 'Her ödemeyi onayla',
  '\\nDecline every payment\\n' => 'Her ödemeyi reddet',
  '\\nNo money is taken. Development only.\\n' => 'Para çekilmez. Yalnızca geliştirme içindir.',
  '\\nTEST MODE: no card is charged.\\n' => 'TEST MODU: karttan ücret alınmaz.',
  '\\nTest provider: the payment was declined.\\n' => 'Test sağlayıcısı: ödeme reddedildi.',
  '[[\'Publishable key\\n' => 'Yayınlanabilir anahtar',
  'Secret key' => 'Gizli anahtar',
  '\\nStripe is not configured on this site. Please contact the site administrator.\\n' => 'Stripe bu sitede yapılandırılmamış. Lütfen site yöneticisiyle iletişime geçin.',
  '\\nThe payment method of this form is not supported.\\n' => 'Bu formun ödeme yöntemi desteklenmiyor.',
  '\\nThe payment could not be started. Please try again.\\n' => 'Ödeme başlatılamadı. Lütfen tekrar deneyin.',
  '\\nOptional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.\\n' => 'İsteğe bağlı ama önerilir: Stripe Dashboard\'da bu URL ve payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated ve customer.subscription.deleted olaylarıyla bir webhook uç noktası ekleyin, ardından imzalama sırrını aşağıya yapıştırın.',
  '\\nWebhook signing secret\\n' => 'Webhook imzalama sırrı',
  '\\nSaved - leave empty to keep it\\n' => 'Kaydedildi - korumak için boş bırakın',
  '\\nRemove the saved secret\\n' => 'Kayıtlı sırrı kaldır',
  '\\nInvalid or expired nonce\\n' => 'Geçersiz veya süresi dolmuş nonce',
  '\\nNo payment provider is available on this site. Please contact the site administrator.\\n' => 'Bu sitede kullanılabilir bir ödeme sağlayıcısı yok. Lütfen site yöneticisiyle iletişime geçin.',
  '\\nToo many payment attempts. Please wait a few minutes and try again.\\n' => 'Çok fazla ödeme denemesi. Lütfen birkaç dakika bekleyip tekrar deneyin.',
  '\\nInvalid payment data. Please refresh the page and try again.\\n' => 'Geçersiz ödeme verisi. Lütfen sayfayı yenileyip tekrar deneyin.',
  '\\nThe payment provider is not configured on this site. Please contact the site administrator.\\n' => 'Ödeme sağlayıcısı bu sitede yapılandırılmamış. Lütfen site yöneticisiyle iletişime geçin.',
  '\\nNo payment amount detected. Please review your selected items and try again. If the problem persists, contact support.\\n' => 'Ödeme tutarı algılanmadı. Lütfen seçtiğiniz öğeleri gözden geçirip tekrar deneyin. Sorun devam ederse destekle iletişime geçin.',
  '\\nToo many requests. Please wait a moment and try again.\\n' => 'Çok fazla istek gönderildi. Lütfen biraz bekleyip tekrar deneyin.',
  '\\nPayment not found.\\n' => 'Ödeme bulunamadı.',
  '\\nYour payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.\\n' => 'Ödemeniz henüz onaylanmadı. Lütfen biraz bekleyip tekrar deneyin. Sorun devam ederse site yöneticisiyle iletişime geçin.',
  '\\nOnline payment is not available at the moment. Please try again later or contact us.\\n' => 'Online ödeme şu anda kullanılamıyor. Lütfen daha sonra tekrar deneyin ya da bizimle iletişime geçin.',
  '\\nActive payment provider\\n' => 'Etkin ödeme sağlayıcısı',
  '\\nPayment forms take card payments through this provider. Only installed providers are listed.\\n' => 'Ödeme formları kart ödemelerini bu sağlayıcı üzerinden alır. Yalnızca kurulu sağlayıcılar listelenir.',
  '\\nSaved — leave empty to keep\\n' => 'Kayıtlı — korumak için boş bırakın',
  '\\n%ssettings\\n' => '%s ayarları',
  '\\nFlux Forms replaces%s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.\\n' => 'Flux Forms, %s eklentisinin yerini aldı; eski eklenti devre dışı bırakıldı. Formlarınız, gelen yanıtlar ve ayarlarınız yerinde duruyor. Eski eklentiyi silebilirsiniz.',
  '\\nUpdating amount...\\n' => 'Tutar güncelleniyor…',
