  '\\nThe Security & Spam Protection admin data could not be loaded. Another plugin may be blocking the script settings, or the page was cached. Reload the page; if it persists, disable admin script optimization for this page.\\n' => 'Güvenlik ve Spam Koruması yönetici verileri yüklenemedi. Başka bir eklenti betik ayarlarını engelliyor olabilir veya sayfa önbelleğe alınmış olabilir. Sayfayı yeniden yükleyin; sorun sürerse bu sayfa için yönetici betik optimizasyonunu devre dışı bırakın.',
  '\\nThe Security & Spam Protection panel failed to render. Reload the page or check the browser console.\\n' => 'Güvenlik ve Spam Koruması paneli görüntülenemedi. Sayfayı yeniden yükleyin veya tarayıcı konsolunu kontrol edin.',
  '\\nProtection is paused: required PHP functions are disabled on this server:%s. Ask your host to remove them from the disable_functions line in php.ini. Your forms keep working without protection until then.\\n' => 'Koruma duraklatıldı: gerekli PHP işlevleri bu sunucuda devre dışı: %s. Barındırıcınızdan bunları php.ini içindeki disable_functions satırından kaldırmasını isteyin. O zamana kadar formlarınız korumasız çalışmaya devam eder.',
  '\\nProtection is paused: the add-on database tables could not be created. Check that the database user can CREATE tables, then reload this page.\\n' => 'Koruma duraklatıldı: eklenti veritabanı tabloları oluşturulamadı. Veritabanı kullanıcısının tablo OLUŞTURABİLDİĞİNDEN (CREATE) emin olun, ardından bu sayfayı yeniden yükleyin.',
