  '\\nFile upload budget\\n' => 'Dosya yükleme bütçesi',
  '\\nFlux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.\\n' => 'Flux Forms yüklemeleri zaten kendisi sınırlar: her ziyaretçi formdaki her dosya alanı için üç dosya yükleyebilir, yanıt kutusu da üç dosyaya izin verir. Bu otomatik davranışı korumak için kutuyu 0 bırakın veya kendiniz ayarlamak için bir sayı girin.',
  '\\nUploads allowed per file field\\n' => 'Dosya alanı başına izin verilen yükleme',
  '\\nDefault 3, so a two-field form allows six uploads. 0 keeps the default.\\n' => 'Varsayılan 3, yani iki alanlı bir form altı yüklemeye izin verir. 0 varsayılanı korur.',
  '\\nTotal uploads per visitor\\n' => 'Ziyaretçi başına toplam yükleme',
  '\\nA fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.\\n' => 'Formda kaç alan olduğuna bakmayan sabit bir toplam. 0 otomatik alan başı hesaplamayı korur.',
  '\\nBudget resets after (seconds)\\n' => 'Bütçe şu süre sonra sıfırlanır (saniye)',
  '\\nDefault 3600 (one hour). 0 keeps the default.\\n' => 'Varsayılan 3600 (bir saat). 0 varsayılanı korur.',
  '\\nMaximum file size (MB)\\n' => 'Maksimum dosya boyutu (MB)',
  '\\nA site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.\\n' => 'Site genelinde bir üst sınır. Alan başına limiti yalnızca daraltabilir, asla genişletemez. 0 alan ayarını korur.',
  '\\nProtect response lookup\\n' => 'Yanıt sorgulamasını koru',
