  '\\nRetest\\n' => 'Yeniden Test Et',
  '\\nLet’s connect Google Sheets — about 3 minutes, one time\', \'en\']]' => 'Google E-Tablolar\'ı bağlayalım — yaklaşık 3 dakika, tek seferlik',
  '\\nFollow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.\\n' => 'Google\'dan ücretsiz bir hizmet hesabı anahtarı indirmek için sağdaki numaralı adımları izleyin, ardından dosyayı aşağıya bırakın. Bunu yalnızca bir kez yaparsınız. Sonrasında herhangi bir form için tablo oluşturmak birkaç tıklama sürer.',
  '\\nYour Google email\\n' => 'Google e-postanız',
  '\\n(recommended)\\n' => '(önerilir)',
  '\\nAny sheet the plugin<strong>creates</strong>is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.\\n' => 'Eklentinin <strong>oluşturduğu</strong> her tablo otomatik olarak bu adresle paylaşılır ve kendi Google Drive\'ınızda “Benimle paylaşılanlar” altında görünür. Bu adres olmadan yeni tablolar hizmet hesabının içinde gizli kalır.',
  '\\nEnable Google Sheet Integration\\n' => 'Google E-Tablolar Entegrasyonunu Etkinleştir',
  '\\nSync form submissions to your spreadsheets automatically\\n' => 'Form gönderimlerini tablolarınızla otomatik senkronize edin',
  '\\nDrag & drop service account JSON file(s) here\\n' => 'Hizmet hesabı JSON dosyalarını buraya sürükleyip bırakın',
  '\\nor click to browse — you can add multiple service accounts at once\\n' => 'veya göz atmak için tıklayın — aynı anda birden fazla hizmet hesabı ekleyebilirsiniz',
  '\\nConnected service accounts\\n' => 'Bağlı hizmet hesapları',
  '\\nOne-time setup (≈3 min)\\n' => 'Tek seferlik kurulum (≈3 dk)',
  '\\nGo to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create\\n' => '<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> adresine gidin &rarr; Proje açılır menüsü (sol üst) &rarr; Yeni Proje &rarr; bir ad verin &rarr; Oluştur',
  '\\nAPIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>\\n' => 'APIs &amp; Services &rarr; Library &rarr; <strong>Google Sheets API</strong> <em>ve</em> <strong>Google Drive API</strong>\'yi etkinleştirin',
  '\\nAPIs & Services → Credentials → Create Credentials → Service Account → name it → Done\\n' => 'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; bir ad verin &rarr; Done',
  '\\nOpen the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)\\n' => 'Hizmet hesabını açın &rarr; Keys sekmesi &rarr; Add Key &rarr; Create New Key &rarr; JSON (otomatik iner)',
  '\\nDrag that downloaded file into the box on the left — it is tested automatically\\n' => 'İndirilen dosyayı soldaki kutuya sürükleyin — otomatik olarak test edilir',
  '\\nAdd<strong>Your Google email</strong>above so created sheets land in your Drive\\n' => 'Oluşturulan tabloların Drive\'ınıza düşmesi için yukarıya <strong>Google e-postanızı</strong> ekleyin',
  '\\nPlease choose a valid .json key file.\\n' => 'Lütfen geçerli bir .json anahtar dosyası seçin.',
  '\\nCould not read file:%s\\n' => 'Dosya okunamadı: %s',
  '\\nConnecting service account...\\n' => 'Hizmet hesabı bağlanıyor…',
  '\\nService account added.\\n' => 'Hizmet hesabı eklendi.',
  '\\nSaved. New sheets created by the plugin will be shared to%sautomatically.\\n' => 'Kaydedildi. Eklentinin oluşturduğu yeni tablolar otomatik olarak %s ile paylaşılacak.',
  '\\nEmail cleared. New sheets will stay inside the service account until you share them.\\n' => 'E-posta temizlendi. Yeni tablolar, siz paylaşana kadar hizmet hesabının içinde kalacak.',
  '\\nRemove this service account?\\n' => 'Bu hizmet hesabı kaldırılsın mı?',
  '\\nConnect each form to a specific Google Sheet tab\\n' => 'Her formu belirli bir Google E-Tablolar sekmesine bağlayın',
  '\\nConnect each form to a specific Google Sheet tab — step by step\\n' => 'Her formu belirli bir Google E-Tablolar sekmesine bağlayın — adım adım',
  '\\nNo service account connected.\\n' => 'Bağlı hizmet hesabı yok.',
  '\\nGo to the Connections tab and drop a service account JSON key first.\\n' => 'Önce Bağlantılar sekmesine gidin ve bir hizmet hesabı JSON anahtarı bırakın.',
  '\\nLast sync OK\\n' => 'Son senkronizasyon başarılı',
  '\\nLast sync failed\\n' => 'Son senkronizasyon başarısız',
  '\\nRemove sync? The sheet stays safe.\\n' => 'Senkronizasyon kaldırılsın mı? Tablonuz güvende kalır.',
  '\\nYes, remove\\n' => 'Evet, kaldır',
  '\\nRemove this sync (your Google Sheet is not deleted)\\n' => 'Bu senkronizasyonu kaldır (Google Tablonuz silinmez)',
  '\\nExisting Bindings\\n' => 'Mevcut Bağlantılar',
  '\\nDelete All\\n' => 'Tümünü Sil',
  '\\nNew Binding\\n' => 'Yeni Bağlantı',
  '\\nSpreadsheet ID\\n' => 'Tablo Kimliği',
  '\\ntab\\n' => 'Sekme',
  '\\nChoose Sheet\\n' => 'Tablo Seç',
  '\\nColumns & Fields\\n' => 'Sütunlar ve Alanlar',
  '\\nStyle & Save\\n' => 'Stil ve Kaydet',
  '\\nWhich form should send data to Google Sheets?\\n' => 'Hangi form verileri Google E-Tablolar\'a göndersin?',
  '\\nPlease select a form first.\\n' => 'Lütfen önce bir form seçin.',
  '\\nService Account\\n' => 'Hizmet Hesabı',
  '\\nLoading your spreadsheets...\\n' => 'Tablolarınız yükleniyor…',
  '\\nClick<strong>“Browse My Sheets”</strong>to list spreadsheets this service account can already access, or<strong>“Create New Sheet”</strong>to make a fresh one.\\n' => 'Bu hizmet hesabının erişebildiği tabloları listelemek için <strong>“Tablolarıma Göz At”</strong>a, yeni bir tablo oluşturmak için <strong>“Yeni Tablo Oluştur”</strong>a tıklayın.',
  '\\n<strong>No spreadsheets are accessible to this service account yet.</strong>You have two options:\\n' => '<strong>Bu hizmet hesabının erişebildiği tablo henüz yok.</strong> İki seçeneğiniz var:',
  '\\n<strong>Easiest:</strong>click<em>“Create New Sheet”</em>above — it is made for you and shared to your email automatically.\\n' => '<strong>En kolayı:</strong> yukarıdaki <em>“Yeni Tablo Oluştur”</em>a tıklayın — sizin için oluşturulur ve e-postanızla otomatik paylaşılır.',
  '\\n<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste\\n' => '<strong>Mevcut bir tabloyu kullanın:</strong> Google E-Tablolar\'da açın &rarr; Paylaş &rarr; şunu yapıştırın:',
  '\\n→ Editor, then click<em>Browse My Sheets</em>again.\\n' => '&rarr; Düzenleyen yapın, ardından <em>Tablolarıma Göz At</em>\'a tekrar tıklayın.',
  '\\nthe service account email\\n' => 'hizmet hesabı e-postası',
  '\\nCreate a new spreadsheet\\n' => 'Yeni bir tablo oluştur',
  '\\nNew spreadsheet title (e.g. Contact form responses)\\n' => 'Yeni tablo başlığı (örn. İletişim formu yanıtları)',
  '\\nYour Google email — the sheet is shared here so you can open it\\n' => 'Google e-postanız — tablo, açabilmeniz için buraya paylaşılır',
  '\\nPre-filled from your saved email.\\n' => 'Kayıtlı e-postanızdan önceden dolduruldu.',
  '\\nLeave empty only if you don’t need to open the sheet yourself.\\n' => 'Tabloyu kendiniz açmanız gerekmiyorsa boş bırakın.',
  '\\nCreate Sheet\\n' => 'Tablo Oluştur',
  '\\nCreating...\\n' => 'Oluşturuluyor…',
  '\\nCreating spreadsheet...\\n' => 'Tablo oluşturuluyor…',
  '\\nSheet created and shared with your email. It’s selected below — click Next to finish.\\n' => 'Tablo oluşturuldu ve e-postanızla paylaşıldı. Aşağıda seçili — bitirmek için İleri\'ye tıklayın.',
  '\\nSheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.\\n' => 'Tablo oluşturuldu. İpucu: yeni tabloların size otomatik paylaşılması için Bağlantılar sekmesine “Google e-postanızı” ekleyin.',
  '\\nOpen the new sheet\\n' => 'Yeni tabloyu aç',
  '\\nSelected:\\n' => 'Seçili:',
  '\\nLoading worksheet tabs...\\n' => 'Çalışma sayfası sekmeleri yükleniyor…',
  '\\nWorksheet Tab\\n' => 'Çalışma Sayfası Sekmesi',
  '\\nOr type a new tab name (created automatically)\\n' => 'Veya yeni bir sekme adı yazın (otomatik oluşturulur)',
  '\\nBrowse My Sheets\\n' => 'Tablolarıma Göz At',
  '\\nCreate New Sheet\\n' => 'Yeni Tablo Oluştur',
  '\\nChoose or create a spreadsheet first\\n' => 'Önce bir tablo seçin veya oluşturun',
  '\\nPlease select a service account.\\n' => 'Lütfen bir hizmet hesabı seçin.',
  '\\nPlease choose or create a spreadsheet first.\\n' => 'Lütfen önce bir tablo seçin veya oluşturun.',
  '\\nEnable Sync for this Form\\n' => 'Bu Form İçin Senkronizasyonu Etkinleştir',
  '\\nDisable to pause without deleting the binding\\n' => 'Bağlantıyı silmeden duraklatmak için devre dışı bırakın',
  '\\nReading this form’s fields...\\n' => 'Bu formun alanları okunuyor…',
  '\\nWe couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry —<strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.\\n' => 'Bu formun alanlarını otomatik okuyamadık, bu nedenle sütun eşleme kullanılamıyor. Endişelenmeyin — <strong>gönderilen her alan yine de otomatik olarak senkronize edilir</strong>; her biri kendi sütununda, gönderim sırasına göre yer alır. Başlık satırı sizin için oluşturulur ve güncel tutulur.',
  '\\nDrag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.\\n' => '<strong>Sütun sırasını</strong> belirlemek için satırları sürükleyin (veya ▲▼ kullanın). İstediğiniz <strong>başlığı</strong> yeniden adlandırın. Bir alanın sütununu atlamak için alanı kapatın. Harf (A, B, C…) her alanın nereye düştüğünü gösterir.',
  '\\nCol\\n' => 'Sütun',
  '\\nSpreadsheet header\\n' => 'Tablo başlığı',
  '\\nOrder / On\\n' => 'Sıra / Açık',
  '\\nRefresh fields from form\\n' => 'Alanları formdan yenile',
  '\\nColumns & Field Mapping\\n' => 'Sütunlar ve Alan Eşleme',
  '\\nSubmitted time\\n' => 'Gönderim zamanı',
  'built-in' => 'yerleşik',
  '\\nSubmitted At\\n' => 'Gönderim Zamanı',
  '\\nColumn header\\n' => 'Sütun başlığı',
  'Drag to reorder' => 'Sıralamak için sürükleyin',
  '\\nInclude this field\\n' => 'Bu alanı dahil et',
  '[[\'%dcolumn will be written to the sheet.\', \'en\']]' . chr(0) . '[[\'%dcolumns will be written to the sheet.\', \'en\']]' => '%d column will be written to the sheet.' . chr(0) . '%d columns will be written to the sheet.',
  '\\nSheet Style\\n' => 'Tablo Stili',
  '\\n(Google theme)\', \'en\']]' => '(Google teması)',
  '[[\'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.\\n' => 'Tablo için bir görünüm seçin — renkli başlık, sabitlenmiş üst satır ve dönüşümlü satır renkleri (Google E-Tablolar\'ın kendi stili). İlk senkronizasyonda otomatik uygulanır veya şimdi uygulayabilirsiniz.',
  '\\nApply style now\\n' => 'Stili şimdi uygula',
  '\\nApplying...\\n' => 'Uygulanıyor…',
  '\\nOptional — it also applies on the first submission.\\n' => 'İsteğe bağlı — ilk gönderimde de uygulanır.',
  '\\nSpreadsheet:\\n' => 'Tablo:',
  '\\nTab:\\n' => 'Sekme:',
  '\\nColumns:\\n' => 'Sütunlar:',
  '\\n%dmapped\\n' => '%d eşlendi',
  '\\nall submitted fields (auto)\\n' => 'gönderilen tüm alanlar (otomatik)',
  '\\nStyle:\\n' => 'Stil:',
  '\\nAfter saving, submit the form once to create the header row and confirm the first sync.\\n' => 'Kaydettikten sonra başlık satırını oluşturmak ve ilk senkronizasyonu doğrulamak için formu bir kez gönderin.',
  '\\nSave Binding\\n' => 'Bağlantıyı Kaydet',
  '[[\'Please choose a spreadsheet first.\\n' => 'Lütfen önce bir tablo seçin.',
  '\\nPick a style first — “None” leaves the sheet unstyled.\\n' => 'Önce bir stil seçin — “Yok” tabloyu stilsiz bırakır.',
  '\\nStyle applied.\\n' => 'Stil uygulandı.',
  '\\nPlease select a form.\\n' => 'Lütfen bir form seçin.',
  '\\nPlease choose a spreadsheet.\\n' => 'Lütfen bir tablo seçin.',
  '\\nBinding saved.\\n' => 'Bağlantı kaydedildi.',
  '\\nRemove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.\\n' => 'Bu bağlantı kaldırılsın mı? Bu form için senkronizasyon durur. Google Tablonuz ve verileri silinmez.',
  '\\nSync removed — your Google Sheet and its data are untouched.\\n' => 'Senkronizasyon kaldırıldı — Google Tablonuza ve verilerine dokunulmadı.',
  '[[\'Remove ALL%dbinding? Syncing stops for every form. Your Google Sheets are not deleted.\', \'en\']]' . chr(0) . '[[\'Remove ALL%dbindings? Syncing stops for every form. Your Google Sheets are not deleted.\', \'en\']]' => 'Remove ALL %d binding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL %d bindings? Syncing stops for every form. Your Google Sheets are not deleted.',
  '\\nAll bindings removed. Your Google Sheets are untouched.\\n' => 'Tüm bağlantılar kaldırıldı. Google Tablolarınıza dokunulmadı.',
  '\\nHelp & Setup Guide\\n' => 'Yardım ve Kurulum Kılavuzu',
  '\\nEverything you need to connect forms to Google Sheets\\n' => 'Formları Google E-Tablolar\'a bağlamak için ihtiyacınız olan her şey',
  '\\nStep-by-Step Setup\\n' => 'Adım Adım Kurulum',
  '\\nCreate or Select a Project\\n' => 'Proje Oluşturun veya Seçin',
  '\\nOpen console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create\', \'en\']]' => 'console.cloud.google.com adresini açıp giriş yapın &rarr; Proje açılır menüsüne (sol üst) tıklayın &rarr; Yeni Proje (veya mevcut birini seçin) &rarr; bir ad girin &rarr; Oluştur',
  '\\nEnable both Google APIs\\n' => 'Her iki Google API\'sini etkinleştirin',
  '\\nAPIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)\\n' => 'APIs &amp; Services &rarr; Library &rarr; <strong>Google Sheets API</strong> ve <strong>Google Drive API</strong>\'yi etkinleştirin (ikisi de gereklidir — Drive dosyaları listeler ve oluşturur)',
  '\\nCreate a Service Account\\n' => 'Hizmet Hesabı Oluşturun',
  '\\nAPIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done\\n' => 'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; bir ad girin &rarr; Done',
  '\\nCreate a JSON Key\\n' => 'JSON Anahtarı Oluşturun',
  '\\nOpen the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)\\n' => 'Hizmet hesabını açın &rarr; Keys sekmesi &rarr; Add Key &rarr; Create New Key &rarr; JSON\'u seçin (dosya otomatik iner)',
  '\\nDrop the Key File\\n' => 'Anahtar Dosyasını Bırakın',
  '\\nDrag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge\\n' => 'İndirilen dosyayı Bağlantılar sekmesine sürükleyin — otomatik doğrulanır ve yeşil bir “Bağlı” rozeti görürsünüz',
  '\\nAdd Your Google Email\\n' => 'Google E-postanızı Ekleyin',
  '\\nOn the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive\\n' => 'Bağlantılar sekmesinde “Google e-postanız” alanını doldurup Kaydedin — eklentinin oluşturduğu tablolar size paylaşılır ve kendi Drive\'ınızda görünür',
  '\\nBind a Form (create a sheet)\\n' => 'Bir Formu Bağlayın (tablo oluşturun)',
  '\\nForm Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path\\n' => 'Form Bağlantıları &rarr; bir form seçin &rarr; <strong>Yeni Tablo Oluştur</strong> &rarr; Kaydet. Elle paylaşım gerekmez — en kolay yol budur',
  '\\n...or use an existing sheet\\n' => '…veya mevcut bir tabloyu kullanın',
  '\\nPrefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard", \'en\']]' => 'Kendi tablonuzu mu tercih ediyorsunuz? Açın &rarr; Paylaş &rarr; hizmet hesabı e-postasını yapıştırın (kartındaki kopyala düğmesi) &rarr; Düzenleyen &rarr; ardından sihirbazda Tablolarıma Göz At\'ı kullanın',
  'FAQ' => 'SSS',
  '\\nI created a sheet — where did it go?\\n' => 'Bir tablo oluşturdum — nereye gitti?',
  '\\nService accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.\\n' => 'Hizmet hesapları dosyaları kendi gizli Drive\'larında oluşturur. Bağlantılar sekmesine “Google e-postanızı” ekleyin; eklenti her yeni tabloyu size otomatik paylaşır ve Google Drive\'ınızda “Benimle paylaşılanlar” altında görünür. Her tablonun bu panelde ayrıca bir “Aç” bağlantısı da vardır.',
  '\\nWhy don’t I see my existing sheet in the picker?\\n' => 'Mevcut tablom neden seçicide görünmüyor?',
  '\\nIt must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.\\n' => 'Önce hizmet hesabının e-postasıyla paylaşılmalıdır: tabloyu açın &rarr; Paylaş &rarr; e-postayı yapıştırın (bağlantı kartındaki kopyala düğmesini kullanın) &rarr; Düzenleyen yapın &rarr; Paylaş. Ardından “Tablolarıma Göz At”a tekrar tıklayın.',
  '\\nTest result: Google API is not enabled.\\n' => 'Test sonucu: Google API etkin değil.',
  '\\nOpen Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.\\n' => 'Aynı proje için Google Cloud Console\'u açın &rarr; APIs &amp; Services &rarr; Library ve HEM “Google Sheets API” HEM DE “Google Drive API”yi etkinleştirin. Bir dakika bekleyin, ardından tekrar test edin.',
  '\\nTest result: Access/Permission denied\\n' => 'Test sonucu: Erişim/İzin reddedildi',
  '\\nThe service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.\\n' => 'Hizmet hesabı kimlik doğrulaması yapabiliyor ancak ilgili tabloya erişemiyor. Tabloyu hizmet hesabı e-postasıyla Düzenleyen olarak yeniden paylaşın veya bunun yerine yeni bir tablo oluşturun.',
  '\\nOpenSSL is required.\\n' => 'OpenSSL gereklidir.',
  '\\nThe server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.\\n' => 'Sunucuda, güvenli Google isteğini imzalamak için kullanılan PHP OpenSSL eklentisi eksik. Hosting sağlayıcınızdan etkinleştirmesini isteyin — hiçbir eklenti ayarı bunun yerini tutamaz.',
  '\\nCan I connect more than one service account?\\n' => 'Birden fazla hizmet hesabı bağlayabilir miyim?',
  '\\nYes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.\\n' => 'Evet — Bağlantılar sekmesine istediğiniz kadar JSON anahtarı bırakın ve her form bağlantısının hangisini kullanacağını seçin.',
  '[[\'Does the connection expire?\\n' => 'Bağlantının süresi dolar mı?',
  '\\nNo. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.\\n' => 'Hayır. Entegrasyon tamamen sunucuda JSON anahtarınızla çalışır — süresi dolacak bir tarayıcı oturumu veya giriş yoktur.',
  '\\nCan I choose which field goes to which column?\\n' => 'Hangi alanın hangi sütuna gideceğini seçebilir miyim?',
  '\\nYes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.\\n' => 'Evet. Bağlantı sihirbazının <strong>Sütunlar &amp; Alanlar</strong> adımında satırları sürükleyerek (veya ▲▼ kullanarak) sırayı belirleyin, her sütun başlığını yeniden adlandırın ve atlamak istediğiniz alanı kapatın. A/B/C rozeti her alanın tam olarak nereye düştüğünü gösterir.',
  '\\nCan I style the sheet automatically?\\n' => 'Tabloyu otomatik olarak biçimlendirebilir miyim?',
  '\\nYes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.\\n' => 'Evet. <strong>Stil &amp; Kaydet</strong> adımı Google E-Tablolar temaları sunar (renkli başlık, sabitlenmiş üst satır, dönüşümlü satır renkleri). Birini seçin; ilk senkronizasyonda uygulanır veya “Stili şimdi uygula”ya tıklayın.',
  '\\nWhat if my form fields change later?\\n' => 'Form alanlarım daha sonra değişirse ne olur?',
  '\\nNew fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.\\n' => 'Yeni alanlar otomatik eklenir. Eşlemeli modda, Sütunlar adımını açıp “Alanları formdan yenile”ye tıklayarak bunları eşlemeye alın; “Tüm Form Alanları” modunda ise sonraki gönderimde yeni sütun olarak görünürler.',
  '\\nWhat if the tab doesn’t exist yet?\\n' => 'Sekme henüz yoksa ne olur?',
  '\\nIt is created automatically the first time a submission is synced.\\n' => 'Bir gönderim ilk senkronize edildiğinde otomatik olarak oluşturulur.',
  '\\nGoogle Sheet Sync Logs\\n' => 'Google E-Tablolar Senkronizasyon Günlükleri',
