  '\\n%1$scannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.\\n' => 'Gerekli PHP işlevleri kullanılamadığı için %1$s çalışamıyor (%2$s). Hosting sağlayıcınızdan gerekli PHP eklentisini etkinleştirmesini isteyin veya listelenen işlevleri php.ini içindeki disable_functions değerinden kaldırın.',
  'Panel' => 'Panel',
