  '\\nInvalid email address\\n' => 'Geçersiz e-posta adresi',
  'Please enter a valid email address.' => 'Lütfen geçerli bir e-posta adresi girin.',
  '\\nInvalid sender email\\n' => 'Geçersiz gönderen e-postası',
  '\\nThe sender email address is not valid.\\n' => 'Gönderen e-posta adresi geçerli değil.',
  '\\nEmail tester service error\\n' => 'E-posta test hizmeti hatası',
  '\\nCould not start email test.\\n' => 'E-posta testi başlatılamadı.',
  '\\nInvalid service response\\n' => 'Geçersiz hizmet yanıtı',
  '\\nThe email tester service returned an invalid response.\\n' => 'E-posta test hizmeti geçersiz bir yanıt döndürdü.',
  '\\nThe message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.\\n' => 'Mesaj web sitenizden hiç çıkmadı: WordPress göndermeye çalışırken bir hata bildirdi. Çözümün gerçekten WordPress veya barındırma tarafında olduğu tek durum budur - genellikle bir SMTP eklentisi veya barındırma firmasının devre dışı bıraktığı PHP mail.',
  '\\nWordPress could not send the test email. The message never left your website, so nothing was delivered.\\n' => 'WordPress test e-postasını gönderemedi. Mesaj web sitenizden hiç çıkmadığı için hiçbir şey teslim edilmedi.',
  '[[\'Email test is waiting for delivery confirmation\\n' => 'E-posta testi teslim onayı bekliyor',
  '\\nWordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.\\n' => 'WordPress test e-postasını gönderdi. Flux Forms, e-postayı hazır olarak işaretlemeden önce teslim sonucunu bekliyor.',
  '\\nWordPress accepted and sent the test email. Waiting for it to arrive.\\n' => 'WordPress test e-postasını kabul etti ve gönderdi. Ulaşması bekleniyor.',
  '\\nThe email tester service returned an invalid JSON response.\\n' => 'E-posta test hizmeti geçersiz bir JSON yanıtı döndürdü.',
  '\\nThe email tester service could not start the test.\\n' => 'E-posta test hizmeti testi başlatamadı.',
  '\\nInvalid test hash\\n' => 'Geçersiz test karması',
  '\\nThe email test hash is not valid.\\n' => 'E-posta testi karması geçerli değil.',
  '\\nYour site could not connect\\n' => 'Siteniz bağlanamadı',
  '[[\'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.\\n' => 'Sitenizden posta test hizmetimize hiçbir bağlantı açılamadı. Bu genellikle hizmetteki bir sorundan değil, sunucunuz veya ağı tarafından engellenen giden trafikten kaynaklanır - bazı barındırıcılar diğer ülkelere yapılan bağlantıları engeller. Barındırma sağlayıcınız bunu doğrulayabilir.',
  '\\nService error\\n' => 'Hizmet hatası',
  '\\nThe email tester service could not return the result.\\n' => 'E-posta test hizmeti sonucu döndüremedi.',
  '\\nThe message never left your website. WordPress reported an error while sending, so nothing could be delivered.\\n' => 'Mesaj web sitenizden hiç çıkmadı. WordPress gönderirken bir hata bildirdi, bu nedenle hiçbir şey teslim edilemedi.',
  '\\nThe email was sent, but it never arrived\\n' => 'E-posta gönderildi ama hiç ulaşmadı',
  '\\nWordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.\\n' => 'WordPress mesajı başarıyla gönderdi, yani siteniz ve bu eklenti üzerine düşeni yaptı. Mesaj WordPress\'ten çıktıktan sonra kayboldu, gecikti veya reddedildi - genellikle alıcı taraf onu spam olarak değerlendirdi veya barındırıcınız giden kuyruktan hiç teslim etmedi.',
  '\\nEmail test failed\', \'en\']]' => 'E-posta testi başarısız',
  '\\nThe email server test could not verify email capability.\\n' => 'E-posta sunucusu testi e-posta gönderme yeteneğini doğrulayamadı.',
  '\\nEmail capability verified\\n' => 'E-posta yeteneği doğrulandı',
  '\\nServer confirmed ability to send emails.\\n' => 'Sunucu e-posta gönderebildiğini doğruladı.',
  '\\nYour emails are being delivered to spam\\n' => 'E-postalarınız spam klasörüne düşüyor',
  '\\nWordPress sent the test email, but delivery has not been confirmed yet.\\n' => 'WordPress test e-postasını gönderdi ancak teslimat henüz doğrulanmadı.',
  '\\nEmail delivery failed:%s\\n' => 'E-posta teslimi başarısız: %s',
  '\\nNo file was received. Please choose a file and try again.\\n' => 'Dosya alınamadı. Lütfen bir dosya seçip tekrar deneyin.',
  '\\nThe file could not be read. Please try attaching it again.\\n' => 'Dosya okunamadı. Lütfen tekrar eklemeyi deneyin.',
  '\\nEnable the Email Notification Feature\\n' => 'E-posta Bildirimi Özelliğini Etkinleştirin',
  '\\nTo receive email notifications from your forms, verify your email server by following these steps:\\n' => 'Formlarınızdan e-posta bildirimi almak için e-posta sunucunuzu şu adımları izleyerek doğrulayın:',
  '\\nGo to the<a href="%s" style="font-weight:600;">Flux Forms Panel</a>\\n' => '<a href="%s" style="font-weight:600;">Flux Forms Paneli</a>\'ne gidin',
  '\\nClick Settings from the top menu\\n' => 'Üst menüden Ayarlar\'a tıklayın',
  '\\nSelect the Email Settings tab\\n' => 'E-posta Ayarları sekmesini seçin',
  '\\nClick "Check Email Server" and wait for the test to finish\\n' => '"E-posta Sunucusunu Kontrol Et"e tıklayın ve testin bitmesini bekleyin',
  '\\nIf the score is above 70 — enable the "This site can send emails" switch and save\\n' => 'Puan 70\'in üzerindeyse "Bu site e-posta gönderebilir" anahtarını etkinleştirip kaydedin',
  '\\nOtherwise, follow the instructions shown in the test results\\n' => 'Aksi halde test sonuçlarında gösterilen yönergeleri izleyin',
  '\\n%snotification\\n' => '%s bildirimi',
  '\\nDisabling this feature may affect the proper functionality of Flux Forms. If you plan to use the%sfeature, please ensure it is enabled.\\n' => 'Bu özelliği devre dışı bırakmak Flux Forms\'un düzgün çalışmasını etkileyebilir. %s özelliğini kullanmayı planlıyorsanız lütfen etkin olduğundan emin olun.',
  '\\nEmail system is working properly.\\n' => 'E-posta sistemi düzgün çalışıyor.',
  '\\nYour server is able to send emails using the default PHP mail system.\', \'en\']]' => 'Sunucunuz varsayılan PHP posta sistemini kullanarak e-posta gönderebiliyor.',
  '\\nEmail system is not available.\\n' => 'E-posta sistemi kullanılamıyor.',
  '\\nThe PHP mail() function is missing. Your server cannot send emails.\\n' => 'PHP mail() işlevi eksik. Sunucunuz e-posta gönderemez.',
  '\\nEmail sending is blocked by server settings.\\n' => 'E-posta gönderimi sunucu ayarları tarafından engelleniyor.',
  '\\nThe mail() function is disabled in your server PHP configuration (php.ini).\\n' => 'mail() işlevi sunucunuzun PHP yapılandırmasında (php.ini) devre dışı.',
  '\\nWordPress mail function not found.\\n' => 'WordPress posta işlevi bulunamadı.',
  '\\nThe wp_mail() function is missing or not available. WordPress email features may be broken.\\n' => 'wp_mail() işlevi eksik veya kullanılamıyor. WordPress e-posta özellikleri bozuk olabilir.',
  '\\nNo email handler configured.\\n' => 'Yapılandırılmış e-posta işleyicisi yok.',
  '\\nYour server has no SMTP host or sendmail path set. Emails may not be delivered.\\n' => 'Sunucunuzda SMTP ana bilgisayarı veya sendmail yolu ayarlanmamış. E-postalar teslim edilmeyebilir.',
  '\\nTest email could not be sent.\\n' => 'Test e-postası gönderilemedi.',
  '\\nIt seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.\\n' => 'WordPress sitenizin test e-postası gönderemediği görünüyor. E-posta sisteminizi elle test etmek için Flux Forms > Ayarlar > E-posta Ayarları sekmesine gidin ve "E-posta Sunucusunu Kontrol Et" düğmesine tıklayın.',
  '\\nInvalid email address.\\n' => 'Geçersiz e-posta adresi.',
  '\\nPlease enter a valid admin email address before testing email delivery.\\n' => 'E-posta teslimini test etmeden önce lütfen geçerli bir yönetici e-posta adresi girin.',
  '\\nInvalid sender email.\\n' => 'Geçersiz gönderen e-postası.',
  '\\nThe sender email address is not valid. Please check your email settings.\\n' => 'Gönderen e-posta adresi geçerli değil. Lütfen e-posta ayarlarınızı kontrol edin.',
  '\\nEmail tester service error.\\n' => 'E-posta test hizmeti hatası.',
  '\\nFlux Forms could not start the email delivery test. Please try again later.\\n' => 'Flux Forms e-posta teslim testini başlatamadı. Lütfen daha sonra tekrar deneyin.',
  '\\nInvalid email tester response.\', \'en\']]' => 'Geçersiz e-posta test hizmeti yanıtı.',
  '\\nInvalid email test.\\n' => 'Geçersiz e-posta testi.',
  '\\nThe email test identifier is invalid. Please start a new test.\\n' => 'E-posta testi tanımlayıcısı geçersiz. Lütfen yeni bir test başlatın.',
  '\\nEmail tester connection error.\\n' => 'E-posta test hizmeti bağlantı hatası.',
  '\\nFlux Forms could not connect to the email tester service.\\n' => 'Flux Forms e-posta test hizmetine bağlanamadı.',
  '\\nEmail delivery test failed.\\n' => 'E-posta teslim testi başarısız oldu.',
  '\\nYour emails are arriving in the spam folder.\\n' => 'E-postalarınız spam klasörüne düşüyor.',
  '\\nThe test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.\\n' => 'Test mesajı teslim edildi ancak teslim edilebilirlik puanı güvenilmeyecek kadar düşük. Bunu düzeltmek için SMTP üzerinden gönderim yapın ve alan adınıza SPF ve DKIM kayıtları ekleyin.',
  '\\nEmail delivery test is pending.\\n' => 'E-posta teslim testi beklemede.',
  '\\nEmail Issue\\n' => 'E-posta Sorunu',
  '\\nFlux Forms Email Warning:\\n' => 'Flux Forms E-posta Uyarısı:',
  '\\nPlan data is missing.\\n' => 'Plan verisi eksik.',
  '\\nInvalid plan data format.\\n' => 'Geçersiz plan verisi biçimi.',
  '\\nInvalid plan type.\\n' => 'Geçersiz plan türü.',
