  '\\nThis check runs once after plugin activation. Please refresh the page in a few moments.\\n' => 'Bu kontrol eklenti etkinleştirildikten sonra bir kez çalışır. Lütfen birkaç dakika sonra sayfayı yenileyin.',
  '\\nSome add-ons need a PHP server change\\n' => 'Bazı eklentiler için PHP sunucusunda değişiklik gerekiyor',
  '\\nFlux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.\\n' => 'Flux Forms, etkilenen her etkin eklentiyi güvenle duraklattı; böylece eklentinin geri kalanı çalışmaya devam edebilir.',
  '\\n(currently enabled and paused)\\n' => '(şu anda etkin ve duraklatıldı)',
  '\\n(not enabled)\\n' => '(etkin değil)',
  '\\ndisabled in php.ini:\\n' => 'php.ini içinde devre dışı:',
  '[["not provided by PHP or its required extension:\\n' => 'PHP veya gerekli uzantısı tarafından sağlanmıyor:',
  '\\nThis usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.\\n' => 'Bu genellikle gerekli PHP uzantısının kurulu olmadığı veya işlevin php.ini içindeki disable_functions listesinde yer aldığı anlamına gelir. Lütfen barındırma sağlayıcınızdan etkinleştirmesini isteyin, ardından bu sayfayı yenileyin.',
  '\\nIf you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.\\n' => 'Bu mesajı görüyorsanız muhtemelen nedenlerden biri şudur: Bir önbellekleme eklentisi yüklüyse ayarlarının gözden geçirilmesi gerekebilir.',
  '\\nPlease also ensure that you have a stable internet connection and try again.\\n' => 'Lütfen ayrıca internet bağlantınızın kararlı olduğundan emin olup tekrar deneyin.',
  'File' => 'Dosya',
  '\\nBuilt with%sYT Form%sby%sWordPress form plugin by whitestudio.team%s\\n' => '%sYT Form%s ile oluşturuldu, %sWordPress form eklentisi whitestudio.team%s',
  '\\nFree WordPress form plugin\\n' => 'Ücretsiz WordPress form eklentisi',
