  '\\nFlux Forms WordPress Plugin\\n' => 'Flux Forms WordPress Eklentisi',
  '\\nThis form requires a payment method. Please add one or change the form type.\\n' => 'Bu form bir ödeme yöntemi gerektiriyor. Lütfen bir ödeme yöntemi ekleyin veya form türünü değiştirin.',
