  '\\nLine\\n' => 'Satır',
  '\\nNo errors detected\\n' => 'Hata algılanmadı',
  '\\nThese errors may interfere with forms built using Flux Forms.\\n' => 'Bu hatalar Flux Forms ile oluşturulan formları etkileyebilir.',
  '\\nThis panel is only visible to site administrators.\\n' => 'Bu panel yalnızca site yöneticileri tarafından görülebilir.',
  '\\njQuery Dependency Issue\\n' => 'jQuery Bağımlılık Sorunu',
  '\\njQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.\\n' => 'jQuery düzgün yüklenmemiş veya kullanılamıyor. AJAX ve etkileşimli form özellikleri düzgün çalışmayabilir.',
  '\\nWhiteStudio.team\\n' => 'WhiteStudio.team',
  '\\nEFB\\n' => 'EFB',
  '[[\'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.\\n' => 'Flux Forms; iletişim formları, ödeme formları, anketler, kayıt formları, çok adımlı formlar, dosya yükleme formları, elektronik imza formları ile ses, video ve ekran kaydı formları oluşturmak için koşullu mantık, e-posta bildirimleri, entegrasyonlar, kayıt yönetimi ve gelişmiş spam koruması sunan ücretsiz ve güçlü bir WordPress form oluşturucu eklentisidir.',
  '\\nWordPress Form Builder Plugin\\n' => 'WordPress Form Oluşturucu Eklentisi',
  '\\nWordPress 5.0 or later; PHP 7.0 or later\\n' => 'WordPress 5.0 veya üzeri; PHP 7.0 veya üzeri',
  '\\nFlux Forms Documentation\\n' => 'Flux Forms Dokümantasyonu',
  '\\nDrag-and-Drop WordPress Form Builder\\n' => 'Sürükle-Bırak WordPress Form Oluşturucu',
  '\\nUnlimited Forms and Form Entries\', \'en\']]' => 'Sınırsız Form ve Form Kaydı',
