  '\\nContact and Inquiry Forms\\n' => 'İletişim ve Bilgi Talebi Formları',
  '\\nSupport and Feedback Forms with Message Tracking\\n' => 'Mesaj Takipli Destek ve Geri Bildirim Formları',
  '\\nSurvey and Poll Forms with Visual Results\\n' => 'Görsel Sonuçlu Anket ve Oylama Formları',
  '\\nStripe and PayPal Payment Forms\\n' => 'Stripe ve PayPal Ödeme Formları',
  '\\nWordPress Login and Registration Forms\\n' => 'WordPress Giriş ve Kayıt Formları',
  '\\nFile Upload Forms\\n' => 'Dosya Yükleme Formları',
  '\\nAudio Recording Forms\\n' => 'Ses Kaydı Formları',
  '\\nVideo Recording Forms\\n' => 'Video Kaydı Formları',
  '\\nScreen Recording Forms with Optional Microphone Audio\\n' => 'İsteğe Bağlı Mikrofon Sesli Ekran Kaydı Formları',
  '\\nPrivate and Restricted-Access Forms\\n' => 'Özel ve Erişimi Kısıtlı Formlar',
  '\\nMulti-Step Forms\\n' => 'Çok Adımlı Formlar',
  '\\nSmart Forms with Conditional Logic\\n' => 'Koşullu Mantıklı Akıllı Formlar',
  '\\nElectronic Signature Forms\\n' => 'Elektronik İmza Formları',
  '\\nLocation Picker Forms with OpenStreetMap and Leaflet\\n' => 'OpenStreetMap ve Leaflet ile Konum Seçici Formlar',
  '\\nJob Application Forms\\n' => 'İş Başvuru Formları',
