  '\\nOrder Forms with Recurring and Subscription Billing\', \'en\']]' => 'Yinelenen ve Abonelik Faturalamalı Sipariş Formları',
  '\\nDrag-and-Drop File Upload Fields\\n' => 'Sürükle-Bırak Dosya Yükleme Alanları',
