  '\\nMultiple-Select Dropdowns and Range Sliders\\n' => 'Çoklu Seçimli Açılır Listeler ve Aralık Kaydırıcıları',
  '\\nRating Stars, 5-Point Scale, NPS and Yes-No Questions\\n' => 'Yıldız Puanlama, 5 Noktalı Ölçek, NPS ve Evet-Hayır Soruları',
  '\\nSwitch and Toggle Fields\\n' => 'Anahtar ve Geçiş Alanları',
  '\\nGregorian, Hijri and Jalali Date Pickers\\n' => 'Miladi, Hicri ve Celali Tarih Seçiciler',
  '\\nTelephone, Mobile and Color Picker Fields\\n' => 'Telefon, Mobil ve Renk Seçici Alanları',
  '\\nMatrix and Table Fields for Structured Data\\n' => 'Yapılandırılmış Veriler için Matris ve Tablo Alanları',
  '\\nAutomatic Email Notifications\\n' => 'Otomatik E-posta Bildirimleri',
