  '\\nDisplay the form name as a heading above the form.\\n' => 'Form adını formun üstünde başlık olarak görüntüleyin.',
  '\\nExtra Class Name\\n' => 'Ek Sınıf Adı',
  '\\nAdd custom CSS classes for styling.\', \'en\']]' => 'Stil vermek için özel CSS sınıfları ekleyin.',
  '\\nDesign\\n' => 'Tasarım',
  '\\nCSS\\n' => 'CSS',
  '\\nSelect a form from the element settings.\\n' => 'Öğe ayarlarından bir form seçin.',
