  '\\n📍 Confirmation Code Finder (Tracking)\', \'en\']]' => '📍 Onay Kodu Bulucu (Takip)',
  '\\n🎨 Flux Forms\\n' => '🎨 Flux Forms',
  '\\nAdd Flux Forms forms to your page\\n' => 'Flux Forms formlarını sayfanıza ekleyin',
  '\\nSelect Form:\\n' => 'Form Seç:',
  '\\nCustom Title (optional):\', \'en\']]' => 'Özel Başlık (isteğe bağlı):',
  '\\nShortcode:\\n' => 'Kısa kod:',
  '\\nRun the email check\\n' => 'E-posta kontrolünü çalıştır',
  '\\nThe last delivery check scored%sout of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.\\n' => 'Son teslimat kontrolü 100 üzerinden %s puan aldı. Mesajlarınız siteden çıkıyor, ancak çoğu posta kutusu bunları spam olarak sınıflandırıyor; bu yüzden formlarınızı dolduranlar bunları görmeyecek. Çözüm, bir SMTP hizmeti üzerinden göndermek ve alan adınız için SPF ve DKIM kayıtları eklemektir.',
  '\\nThe last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.\\n' => 'Son teslimat kontrolü, mesajlarınızın siteden çıktığını ancak posta kutularının bunları spam olarak sınıflandırdığını gösterdi. Çözüm, bir SMTP hizmeti üzerinden göndermek ve alan adınız için SPF ve DKIM kayıtları eklemektir.',
  '\\nYour form emails are going to the spam folder\\n' => 'Form e-postalarınız spam klasörüne düşüyor',
  '[[\'Your form emails are sent, but they are not arriving\\n' => 'Form e-postalarınız gönderiliyor ancak ulaşmıyor',
  '\\nWordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.\\n' => 'WordPress son test mesajını başarıyla gönderdi, yani siteniz ve bu eklenti üzerine düşeni yaptı — mesaj WordPress\'ten çıktıktan sonra kayboldu, gecikti veya reddedildi. Genellikle alıcı posta kutusu bunu spam saydı ya da hosting sağlayıcınız giden kuyruktan hiç teslim etmedi. Çözüm, alan adınız için SPF ve DKIM kayıtlarıyla bir SMTP hizmeti üzerinden göndermektir.',
  '\\nWordPress cannot send your form emails\\n' => 'WordPress form e-postalarınızı gönderemiyor',
  '\\nThe last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.\\n' => 'Son kontrol bir mesajı posta sunucunuza bile teslim edemedi: WordPress gönderim sırasında hata bildirdi, yani siteden hiçbir şey çıkmadı. Başlamak için bir SMTP eklentisi kullanın veya hosting sağlayıcınıza PHP mail\'in devre dışı olup olmadığını sorun.',
  '\\nYour form emails are not being delivered\', \'en\']]' => 'Form e-postalarınız teslim edilmiyor',
  '\\nThe last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.\\n' => 'Son teslimat kontrolünde hiçbir mesaj ulaştırılamadı, yani formlarınızın gönderdiği hiçbir şey kimseye ulaşmıyor. Hosting sunucuları genellikle güvenilir bir imza olmadan e-posta gönderir; standart çözüm bir SMTP hizmeti üzerinden göndermektir.',
  '\\nOnce Weekly (Flux Forms)\\n' => 'Haftada Bir (Flux Forms)',
  '\\nThe weekly email delivery test completed successfully.\\n' => 'Haftalık e-posta teslimat testi başarıyla tamamlandı.',
  '\\nThe weekly email delivery test found an email delivery problem.\\n' => 'Haftalık e-posta teslimat testi bir e-posta teslimat sorunu tespit etti.',
  '\\nThe main WordPress administrator email address is not valid.\\n' => 'Ana WordPress yönetici e-posta adresi geçerli değil.',
  '\\nCould not start the email delivery test.\\n' => 'E-posta teslimat testi başlatılamadı.',
  '\\nWordPress sent the automated test email and is waiting for it to arrive.\\n' => 'WordPress otomatik test e-postasını gönderdi ve ulaşmasını bekliyor.',
  '\\nWordPress could not send the automated test email. The message never left this website.\\n' => 'WordPress otomatik test e-postasını gönderemedi. Mesaj bu web sitesinden hiç çıkmadı.',
  '\\nThe email delivery test timed out before confirmation was received.\\n' => 'E-posta teslimat testi, onay alınamadan zaman aşımına uğradı.',
  '\\nWeekly Flux Forms report for%s\\n' => '%s için haftalık Flux Forms raporu',
  '\\nHere is your weekly snapshot for%s.\\n' => 'İşte %s için haftalık özetiniz.',
  '[[\'Report generated%s\\n' => 'Rapor oluşturulma zamanı: %s',
  '\\nDetailed analysis\\n' => 'Ayrıntılı analiz',
  'This week' => 'Bu hafta',
  '\\nEmails failed\\n' => 'Başarısız e-postalar',
  '\\nYou can turn these reports off in Flux Forms settings.\\n' => 'Bu raporları Flux Forms ayarlarından kapatabilirsiniz.',
  '\\nThe test email was delivered, but its deliverability score is only%1$sout of 100 (below%2$s), so the emails your forms send are very likely to be rejected or filtered as spam.\\n' => 'Test e-postası teslim edildi, ancak teslim edilebilirlik puanı 100 üzerinden yalnızca %1$s (%2$s altında); bu nedenle formlarınızın gönderdiği e-postaların reddedilmesi veya spam olarak filtrelenmesi çok olasıdır.',
  '\\nRun the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.\\n' => 'Formlarınızın gönderdiği mesajların gerçekten insanlara ulaştığından emin olmak için e-posta kontrolünü çalıştırın. Kontrol, yeni WhiteStudio teslimat hizmeti üzerinden gerçek bir mesaj gönderir ve nelerin ulaştığını bildirir.',
  '\\nRead the guide to sending email through SMTP\\n' => 'SMTP ile e-posta gönderme kılavuzunu okuyun',
  '\\nDelivery has not been scored yet\\n' => 'Teslimat henüz puanlanmadı',
  '\\nWordPress sent your email, but it never arrived\\n' => 'WordPress e-postanızı gönderdi, ancak ulaşmadı',
  '\\nWordPress could not send your email\', \'en\']]' => 'WordPress e-postanızı gönderemedi',
  '\\nWe could not confirm your emails are being delivered\\n' => 'E-postalarınızın teslim edildiğini doğrulayamadık',
  '\\nout of 100\\n' => '100 üzerinden',
  '\\nYour email delivery is healthy\\n' => 'E-posta teslimatınız sağlıklı',
  '\\nYour emails are likely going to spam\\n' => 'E-postalarınız büyük olasılıkla spam\'e düşüyor',
  '\\nYour emails are not reaching anybody\\n' => 'E-postalarınız kimseye ulaşmıyor',
  '\\ngrade%s\\n' => 'not: %s',
  '\\nWhat you should do\\n' => 'Ne yapmalısınız',
  '\\nA hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.\\n' => 'Hosting sunucuları genellikle güvenilir bir imza olmadan e-posta gönderir; bu da form e-postalarınızı spam klasörüne düşürür veya hiç ulaşmasını engeller. Standart çözüm, bir SMTP hizmeti üzerinden göndermektir.',
  '\\nInstall an SMTP plugin and enter the details of your email service.\\n' => 'Bir SMTP eklentisi kurun ve e-posta hizmetinizin bilgilerini girin.',
  '\\nAdd the SPF and DKIM records to your domain settings.\\n' => 'SPF ve DKIM kayıtlarını alan adı ayarlarınıza ekleyin.',
  '\\nRun the email check again until the score is above%s.\\n' => 'Puan %s üzerine çıkana kadar e-posta kontrolünü tekrar çalıştırın.',
  '\\nYou have%1$sforms:%2$sactive and%3$sinactive.\\n' => 'Toplam %1$s formunuz var: %2$s aktif, %3$s pasif.',
  '\\nRenew Flux Forms Pro\\n' => 'Flux Forms Pro\'yu Yenile',
  '\\nGet more from Flux Forms Pro\\n' => 'Flux Forms Pro\'dan daha fazlasını edinin',
  '\\nRenew your subscription to restore all Pro features and add-ons.\\n' => 'Tüm Pro özelliklerini ve eklentileri geri getirmek için aboneliğinizi yenileyin.',
  '\\nUnlock premium add-ons, unlimited features and priority support for your forms.\\n' => 'Formlarınız için premium eklentilerin, sınırsız özelliklerin ve öncelikli desteğin kilidini açın.',
  '\\nRenew Pro\\n' => 'Pro\'yu Yenile',
  '\\nEmail delivery is working\\n' => 'E-posta teslimatı çalışıyor',
  '\\nThe automated Flux Forms email delivery test completed successfully.\\n' => 'Otomatik Flux Forms e-posta teslimat testi başarıyla tamamlandı.',
  '[[\'You can attach up to%1$dfile here. Please wait about%2$dminutes before trying again.\', \'en\']]' . chr(0) . '[[\'You can attach up to%1$dfiles here. Please wait about%2$dminutes before trying again.\', \'en\']]' => 'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.',
  '\\nThis file is too large. The maximum size for this field is%s.\\n' => 'Bu dosya çok büyük. Bu alan için izin verilen en büyük boyut %s.',
  '\\nThis file type is not accepted here. Please attach one of the file types listed on the field.\\n' => 'Bu dosya türü burada kabul edilmiyor. Lütfen alanda listelenen dosya türlerinden birini ekleyin.',
  '\\nThis file appears to be empty. Please choose a different file.\\n' => 'Bu dosya boş görünüyor. Lütfen farklı bir dosya seçin.',
  '\\nThe uploaded file could not be verified. Please attach it again.\\n' => 'Yüklenen dosya doğrulanamadı. Lütfen tekrar ekleyin.',
  '\\nX-WP-Nonce header is missing\\n' => 'X-WP-Nonce üstbilgisi eksik',
  '\\nYour form session has expired. Please reload the page.\\n' => 'Form oturumunuzun süresi doldu. Lütfen sayfayı yenileyin.',
  '\\nForm ID:\\n' => 'Form ID:',
  '\\nThe form will be displayed on the frontend.\\n' => 'Form ön yüzde görüntülenecektir.',
  '\\nThis link uses an older format. For improved security, new email notifications include updated links.\\n' => 'Bu bağlantı eski bir biçim kullanıyor. Daha iyi güvenlik için yeni e-posta bildirimleri güncel bağlantılar içerir.',
  '\\nIt seems that you are the admin of this form. Please log in and try again.\\n' => 'Bu formun yöneticisi olduğunuz görünüyor. Lütfen oturum açıp tekrar deneyin.',
  '\\nFlux Forms couldn\\\'t locate the form settings. Please check your settings or contact support for assistance.\\n' => 'Flux Forms form ayarlarını bulamadı. Lütfen ayarlarınızı kontrol edin veya yardım için destekle iletişime geçin.',
  '\\nY/m/d \\\\a\\\\t g:ia\\n' => 'd.m.Y \\s\\a\\a\\t H:i',
  '\\nToo many attempts. Please wait a few minutes and try again.\\n' => 'Çok fazla deneme. Lütfen birkaç dakika bekleyip tekrar deneyin.',
  '[[\'The recording upload could not be verified. Please record it again and retry.\\n' => 'Kayıt yüklemesi doğrulanamadı. Lütfen tekrar kaydedip yeniden deneyin.',
  '\\nThis recording format is not supported. Please record it again.\\n' => 'Bu kayıt biçimi desteklenmiyor. Lütfen tekrar kaydedin.',
  '\\nThe server could not verify the recording format. Please contact the site administrator.\\n' => 'Sunucu kayıt biçimini doğrulayamadı. Lütfen site yöneticisiyle iletişime geçin.',
  '\\nThe recording format could not be verified. Please record it again.\\n' => 'Kayıt biçimi doğrulanamadı. Lütfen tekrar kaydedin.',
  '\\nThe server could not verify the recording duration. Please record it again and try uploading.\\n' => 'Sunucu kayıt süresini doğrulayamadı. Lütfen tekrar kaydedip yüklemeyi deneyin.',
  '\\nThe server could not store the recording. Please try again or contact the site administrator.\\n' => 'Sunucu kaydı depolayamadı. Lütfen tekrar deneyin veya site yöneticisiyle iletişime geçin.',
  '\\nThe recording request could not be verified. Please retry.\', \'en\']]' => 'Kayıt isteği doğrulanamadı. Lütfen tekrar deneyin.',
  '\\nThe upload request could not be verified. Please try again.\\n' => 'Yükleme isteği doğrulanamadı. Lütfen tekrar deneyin.',
  '\\nThe upload field could not be verified. Please refresh the form and try again.\\n' => 'Yükleme alanı doğrulanamadı. Lütfen formu yenileyip tekrar deneyin.',
