  'Show or hide fields and steps based on the answers to other fields. Rules run from the lowest priority number to the highest; when two rules change the same field, the later one wins. A field targeted by a "Show field" action stays hidden until its rule matches. Hidden fields are skipped by validation and their values are discarded on the server.' => 'Diğer alanların yanıtlarına göre alanları ve adımları gösterin veya gizleyin. Kurallar en düşük öncelik numarasından en yükseğe doğru çalışır; iki kural aynı alanı değiştirirse sonraki kural geçerli olur. "Alanı göster" eylemiyle hedeflenen bir alan, kuralı eşleşene kadar gizli kalır. Gizli alanlar doğrulamada atlanır ve değerleri sunucuda silinir.',
  'No rules yet. Click "Add rule" to create your first IF / THEN rule.' => 'Henüz kural yok. İlk EĞER / O ZAMAN kuralınızı oluşturmak için "Kural ekle"ye tıklayın.',
