  'Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'Form etkinliği toplamlarınızı &ndash; formlar, görüntülemeler ve gönderimler &ndash; sitenizin ana yöneticiye gönderdiği haftalık e-postaya ekler. Bu toplamlar kendi sitenizde okunur ve asla WhiteStudio\'ya gönderilmez.',
