  'There was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.' => 'Dosya yüklenirken bir sorun oluştu ve form gönderilmedi. Lütfen internet bağlantınızın kararlı olduğunu kontrol edin ve tekrar deneyin.',
