  'Offline Forms Add-on' => 'Çevrimdışı Formlar Eklentisi',
  'The Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.' => 'Flux Forms için Çevrimdışı Formlar eklentisi, kullanıcıların çevrimdışı durumlarda formları doldururken ilerlemelerini kaydetmelerine olanak tanır.',
