  'Before activating this option, install' => 'Bu seçeneği etkinleştirmeden önce şunu yükleyin:',
  'To create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.' => 'Çevrimiçi ödeme toplamak için bir ödeme formu oluşturmak üzere önce Stripe Eklentisi gibi bir ödeme eklentisi yüklemelisiniz.',
  'All formats' => 'Tüm biçimler',
  'EFB SMS Add-on' => 'EFB SMS Eklentisi',
  'Enable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.' => 'EFB SMS eklentisiyle formlarınızda SMS özelliğini etkinleştirin; cep telefonu numaralarını doğrulayın, SMS ile onay kodları gönderin ve SMS hizmeti üzerinden bildirim alın.',
  'Advanced confirmation code Add-on' => 'Gelişmiş onay kodu Eklentisi',
  'Send a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.' => 'Kullanıcılara ve/veya yöneticilere e-posta veya SMS ile onay kodu göndererek yeni yanıtlara hızlıca erişmelerini sağlayın.',
  'Box Checklist' => 'Kutu Kontrol Listesi',
  'Radio Checklist' => 'Radyo Kontrol Listesi',
