  'Persia Payment Add-on' => 'Persia Ödeme Eklentisi',
  'The Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.' => 'Flux Forms için Persia ödeme eklentisi, web sitenizi Persia ödeme ile bağlayarak ödemeleri, bağışları ve çevrimiçi siparişleri işlemenizi sağlar.',
  'Jalali Date Add-on' => 'Celali Tarih Eklentisi',
  'The Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.' => 'Celali Tarih eklentisi, formlarınıza Celali tarih alanı eklemenizi ve bu Şemsi tarih alanını içeren her türlü formu oluşturmanızı sağlar.',
  'Hijri Date Add-on' => 'Hicri Tarih Eklentisi',
  'The Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.' => 'Hicri Tarih eklentisi, formlarınıza Hicri tarih alanı eklemenizi ve bu alanı içeren her türlü formu oluşturmanızı sağlar.',
  'SMS service Add-on' => 'SMS hizmeti Eklentisi',
  'The SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.' => 'SMS hizmeti eklentisi, siz veya müşterileriniz yeni mesaj ya da yanıt aldığında bildirim SMS\'leri almanızı sağlar.',
  'Please install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.' => 'Lütfen Hicri veya Celali tarih eklentilerinden yalnızca birini yükleyin. İki eklentiyi aynı anda yükleyemezsiniz.',
  'Response box' => 'Yanıt kutusu',
  'Regions Drop-Down' => 'Bölgeler Açılır Listesi',
  'You are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.' => 'Bu mesajı, gerekli eklentileriniz yüklendiği için görüyorsunuz. Lütfen birkaç dakika bekleyip bu sayfayı yeniden ziyaret edin. Beş dakikadan uzun süre geçtiyse ve bir şey olmadıysa, lütfen Whitestudio.team adresindeki Flux Forms destek ekibiyle iletişime geçin.',
