  'The confirmation code for this message is %s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.' => 'Bu mesajın onay kodu %s. Aşağıdaki düğmeye tıklayarak mesajları takip edebilir ve alınan yanıtları görüntüleyebilirsiniz. Gerekirse yeni bir yanıt da gönderebilirsiniz.',
  'To explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our %1$s documentation %2$s .' => 'E-posta yapılandırmaları, form oluşturma seçenekleri ve diğer özellikler dahil Flux Forms\'un tüm işlevlerini ve ayarlarını keşfetmek için %1$s dokümantasyonumuza %2$s göz atmanız yeterli.',
  'Responses & Confirmation' => 'Yanıtlar ve Onay',
  'Test emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings %1$sLearn how to fix email delivery issues%2$s or %3$scontact Flux Forms support%4$s.' => 'Test e-postaları spam klasörünüze düşebilir. E-postalar iletilmiyorsa bu genellikle barındırma veya e-posta sunucusu yapılandırmanızla ilgilidir. sunucu ayarları %1$sE-posta teslim sorunlarını nasıl çözeceğinizi öğrenin%2$s veya %3$sYT Form desteğiyle iletişime geçin%4$s.',
  'From Address' => 'Gönderen Adresi',
  'Make sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.' => 'E-posta teslim sorunlarını önlemek için bu e-posta adresinin SMTP ayarlarınızda yapılandırılan adresle eşleştiğinden emin olun.',
  'To preview the form, you need to save the built form and try again.' => 'Formu önizlemek için oluşturduğunuz formu kaydetmeniz ve tekrar denemeniz gerekir.',
