  'After changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.' => 'Geliştirme Modu (Sandbox) seçeneğini değiştirdikten sonra ayarları kaydedin, ardından değişikliklerin geçerli olması için Flux Forms eklentisini Eklentiler sayfasından devre dışı bırakıp yeniden etkinleştirin.',
