  'The connection was interrupted, but don\'t worry—your edits are safely stored in your browser. Refresh the page to continue working.' => 'Bağlantı kesildi ancak endişelenmeyin—düzenlemeleriniz tarayıcınızda güvenle saklanıyor. Çalışmaya devam etmek için sayfayı yenileyin.',
