  'Go to the add-ons page in the Flux Forms plugin, install the %s add-on, and try again.' => 'Flux Forms eklentisindeki eklentiler sayfasına gidin, %s eklentisini yükleyin ve tekrar deneyin.',
  'To create a payment form to collect online payments, install a payment add-on such as the %s Add-on first.' => 'Çevrimiçi ödeme toplayan bir ödeme formu oluşturmak için önce %s Eklentisi gibi bir ödeme eklentisi yükleyin.',
  'Thank' => 'Teşekkürler',
