  'verify' => 'doğrula',
  'The form cannot be submitted because it requires a payment method, which is currently missing. If you are the Admin, please add a payment method to the form or change the form type to "Form" or "Survey".' => 'Form, şu anda eksik olan bir ödeme yöntemi gerektirdiği için gönderilemiyor. Yöneticiyseniz lütfen forma bir ödeme yöntemi ekleyin veya form türünü "Form" ya da "Anket" olarak değiştirin.',
  'Cache Plugin Detected' => 'Önbellek Eklentisi Algılandı',
  'The following cache plugins may interfere with form functionality. If you experience issues, please review the documentation.' => 'Aşağıdaki önbellek eklentileri form işleyişini etkileyebilir. Sorun yaşarsanız lütfen belgelere göz atın.',
  'Read more about cache compatibility' => 'Önbellek uyumluluğu hakkında daha fazla bilgi edinin',
  'Dismiss All' => 'Tümünü Kapat',
  'Dismiss %s' => '%s öğesini kapat',
  'Security Plugin Detected' => 'Güvenlik Eklentisi Algılandı',
  'The following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.' => 'Aşağıdaki güvenlik eklentisi form gönderimlerini 403 hatalarıyla engelleyebilir. REST API\'yi engelleyebilir, X-WP-Nonce başlığını kaldırabilir veya form isteklerine güvenlik duvarı kuralları uygulayabilir.',
  'Read more about security plugin compatibility' => 'Güvenlik eklentisi uyumluluğu hakkında daha fazla bilgi edinin',
  'Auto-Populate Add-on' => 'Otomatik Doldurma Eklentisi',
  'The Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.' => 'Otomatik Doldurma eklentisi, form alanlarını veri kümelerinden, daha önce gönderilen formlardan veya harici API\'lerden otomatik olarak doldurmanızı sağlar.',
  'Form Security & Spam Protection' => 'Form Güvenliği ve Spam Koruması',
  'Behavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.' => 'Hız sınırları ve SMS, Telegram, e-posta ve webhook gibi ücretli bildirimler için zarar durdurma özelliğiyle davranış tabanlı spam ve API kötüye kullanım koruması.',
  'Google Sheet Add-on' => 'Google Sheet Eklentisi',
  'Automatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.' => 'Form gönderimlerini gerçek zamanlı olarak Google E-Tablolarınıza otomatik gönderin. Bir hizmet hesabı bağlayın, alanları sütunlarla eşleyin ve her yanıtın canlı, biçimlendirilmiş bir e-tablosunu tutun — webhook veya tarayıcı girişi gerekmez.',
  'Please fill in all required fields' => 'Lütfen tüm zorunlu alanları doldurun',
  'Email Server Status' => 'E-posta Sunucusu Durumu',
  'The test email never arrived' => 'Test e-postası ulaşmadı',
  'Your WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.' => 'WordPress siteniz e-postaları güvenilir şekilde gönderemiyor. Bu çok yaygın bir barındırma sorunudur — varsayılan PHP mail işlevi sıklıkla engellenir veya spam\'e düşer. Bir SMTP eklentisi kurmak e-postalarınızı doğrulanmış bir posta hizmeti üzerinden yönlendirir ve bunu dakikalar içinde çözer.',
  'WordPress sent the email - it just never arrived' => 'WordPress e-postayı gönderdi - ancak e-posta hiç ulaşmadı',
  'Your site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'Siteniz mesajı posta sunucunuza başarıyla teslim etti; yani WordPress ve bu eklenti üzerine düşeni yaptı. Mesaj sonrasında kayboldu, gecikti veya reddedildi - çoğunlukla alıcının posta kutusu onu spam olarak işaretlemiş veya barındırma sağlayıcınız onu giden kuyruktan hiç teslim etmemiştir. Bunu çözen şey, alan adınız için SPF ve DKIM kayıtlarıyla bir SMTP hizmeti üzerinden göndermektir.',
  'WordPress could not send the email' => 'WordPress e-postayı gönderemedi',
  'The message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.' => 'Mesaj web sitenizden hiç çıkmadı: WordPress gönderirken bir hata döndürdü. Bir SMTP eklentisi kurup yapılandırın veya barındırma sağlayıcınıza PHP mail\'in devre dışı olup olmadığını sorun.',
  'Your emails arrive, but will most likely land in spam' => 'E-postalarınız ulaşıyor ancak büyük olasılıkla spam\'e düşecek',
  'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.' => 'Teslimatın kendisi çalışıyor - test mesajı bize ulaştı. Eksik olan güven: bir SMTP hizmeti üzerinden göndermek ve alan adınız için SPF ve DKIM kayıtları eklemek, e-postalarınızı spam klasöründen gelen kutusuna taşır.',
  'The test email was delivered with a deliverability score of %1$s out of 100. Under %2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.' => 'Test e-postası 100 üzerinden %1$s teslim edilebilirlik puanıyla teslim edildi. %2$s altında çoğu posta kutusu mesajları spam klasörüne koyar; bu nedenle formlarınızı dolduran kişiler onları hiç göremeyebilir.',
  'Step-by-step SMTP setup guide' => 'Adım adım SMTP kurulum rehberi',
  'Your email server is working. A detailed HTML report has been sent to %s.' => 'E-posta sunucunuz çalışıyor. Ayrıntılı bir HTML raporu %s adresine gönderildi.',
  'your admin email address' => 'yönetici e-posta adresiniz',
  'Spam Score Report on the Way!' => 'Spam Puanı Raporu Yolda!',
  'A complete email health report — including your spam score, deliverability details, and recommendations — will be sent to %s within the next few minutes.' => 'Spam puanınız, teslim edilebilirlik ayrıntıları ve önerileri içeren eksiksiz bir e-posta sağlık raporu önümüzdeki birkaç dakika içinde %s adresine gönderilecek.',
  'Email notifications may not be delivered' => 'E-posta bildirimleri teslim edilmeyebilir',
  'This form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is %s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.' => 'Bu formun e-posta bildirimi özelliği etkin ancak e-posta teslimatı doğrulanmadı ve son spam puanı %s/100. Form kaydedildi, ancak SMTP/e-posta teslimatı düzeltilene kadar yönetici bildirim e-postaları size ulaşmayabilir.',
  'Notification emails are turned off' => 'Bildirim e-postaları kapalı',
  'Flux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.' => 'E-posta Ayarları\'nda "Bu site e-posta gönderebilir" etkinleştirilene kadar Flux Forms ne size ne de bu formu gönderen kişiye hiçbir e-posta göndermeyecektir.',
  'Enable email sending' => 'E-posta göndermeyi etkinleştir',
  'Click "Check Email Server" to test delivery, turn this switch on, then press Save.' => 'Teslimatı test etmek için "E-posta Sunucusunu Kontrol Et"e tıklayın, bu anahtarı açın, ardından Kaydet\'e basın.',
  'Delivery is taking longer than expected' => 'Teslimat beklenenden uzun sürüyor',
  'WordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.' => 'WordPress test e-postasını gönderdi ancak sunucumuz henüz almadı. Bu geçici bir gecikme olabilir. Sorunu gidermek için aşağıdaki tanılamaları kontrol edin.',
  'Prepare Test' => 'Testi Hazırla',
  'Connecting to WhiteStudio to generate a unique test email address.' => 'Benzersiz bir test e-posta adresi oluşturmak için WhiteStudio\'ya bağlanılıyor.',
  'WordPress Sends the Email' => 'WordPress E-postayı Gönderir',
  'WordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.' => 'WordPress gerçek bir mesajı posta sunucunuza iletir. Buradaki onay işareti, WordPress\'in gönderdiği anlamına gelir; henüz ulaştığı anlamına gelmez.',
  'Waiting for Delivery' => 'Teslimat Bekleniyor',
  'Checking whether the test email arrived at our server (usually takes a few seconds).' => 'Test e-postasının sunucumuza ulaşıp ulaşmadığı kontrol ediliyor (genellikle birkaç saniye sürer).',
  'Quick Result' => 'Hızlı Sonuç',
  'Showing the first delivery result — you will see right away if email is working.' => 'İlk teslimat sonucu gösteriliyor — e-postanın çalışıp çalışmadığını hemen görürsünüz.',
  'Full Report' => 'Tam Rapor',
  'A detailed HTML report with full diagnostics is being prepared and emailed to you.' => 'Tam tanılama içeren ayrıntılı bir HTML raporu hazırlanıyor ve size e-postayla gönderiliyor.',
  'Needs attention' => 'Dikkat gerekiyor',
