  'Waiting for the email to arrive' => 'E-postanın ulaşması bekleniyor',
  'We check our server every few seconds. Please keep this page open.' => 'Sunucumuzu birkaç saniyede bir kontrol ediyoruz. Lütfen bu sayfayı açık tutun.',
  'Your email server is healthy' => 'E-posta sunucunuz sağlıklı',
  'The test email arrived, and the subject and unique-code checks both passed.' => 'Test e-postası ulaştı; konu ve benzersiz kod kontrollerinin ikisi de başarılı oldu.',
  'Delivered, but likely to be filtered as spam' => 'Teslim edildi ancak büyük olasılıkla spam olarak filtrelenecek',
