  'Your subscription needs renewing before the missing add-ons can be restored.' => 'Eksik eklentilerin geri yüklenebilmesi için aboneliğinizin yenilenmesi gerekiyor.',
  'The missing add-on files could not be restored. Check the server connection and file permissions, then try again.' => 'Eksik eklenti dosyaları geri yüklenemedi. Sunucu bağlantısını ve dosya izinlerini kontrol edip tekrar deneyin.',
  'You do not have permission to do this.' => 'Bunu yapmaya yetkiniz yok.',
  'All required add-ons were restored.' => 'Gerekli tüm eklentiler geri yüklendi.',
  'Finish updating Flux Forms' => 'Flux Forms güncellemesini tamamlayın',
  'Some add-on files are missing' => 'Bazı eklenti dosyaları eksik',
  'The plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.' => 'Eklenti güncellendi; bu sayfa yüklenmeden önce eklentilerinin yeniden yüklenmesi gerekiyor. Yüklemek için aşağıdaki düğmeye tıklayın.',
  'One or more add-on files are missing. Click the button below to reinstall them.' => 'Bir veya daha fazla eklenti dosyası eksik. Yeniden yüklemek için aşağıdaki düğmeye tıklayın.',
  'Automatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.' => 'Otomatik kurtarma denendi ancak tamamlanamadı. Aşağıdaki nedeni inceleyin, gerekirse düzeltin ve tekrar deneyin.',
  'Recover add-ons' => 'Eklentileri kurtar',
  'Installing add-ons…' => 'Eklentiler yükleniyor…',
  'Installation complete.' => 'Yükleme tamamlandı.',
  'Click to activate the add-ons.' => 'Eklentileri etkinleştirmek için tıklayın.',
  'Activate add-ons' => 'Eklentileri etkinleştir',
  'Installation failed. Please try again.' => 'Yükleme başarısız oldu. Lütfen tekrar deneyin.',
  'Missing add-ons:' => 'Eksik eklentiler:',
  'Why the recovery failed' => 'Kurtarma neden başarısız oldu',
  'Preparing your form' => 'Formunuz hazırlanıyor',
  'Add-ons restored successfully' => 'Eklentiler başarıyla geri yüklendi',
  'The form is being prepared. This page will reload automatically.' => 'Form hazırlanıyor. Bu sayfa otomatik olarak yeniden yüklenecek.',
  'The page will reload automatically so the restored add-ons can be activated.' => 'Geri yüklenen eklentilerin etkinleştirilebilmesi için sayfa otomatik olarak yeniden yüklenecek.',
  'Reload now' => 'Şimdi yeniden yükle',
  'This form is temporarily unavailable.' => 'Bu form geçici olarak kullanılamıyor.',
  'We could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.' => 'Gerekli bir form bileşeni otomatik olarak geri yüklenemedi. Lütfen kısa süre sonra tekrar deneyin; site yöneticisi tam kurtarma hatasını Flux Forms içinde görüntüleyebilir.',
  'The add-on is already installed.' => 'Eklenti zaten yüklü.',
  'File access status not checked yet. Please wait.' => 'Dosya erişim durumu henüz kontrol edilmedi. Lütfen bekleyin.',
  'Error: server (%s) responded with an invalid request. responded code: %s' => 'Hata: sunucu (%s) geçersiz bir istekle yanıt verdi. Yanıt kodu: %s',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the %s server' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti %s sunucusuna bağlanamıyor',
  'Your Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:' => 'Flux Forms Pro aboneliğinizin süresi doldu, bu nedenle Pro eklentileri indirilemedi. Eklenti bunlar olmadan çalışmaya devam eder. Tüm Pro özelliklerini geri yüklemek için aboneliğinizi yenileyin:',
  'The version of the add-on is not compatible with the version of the Flux Forms plugin.' => 'Eklentinin sürümü Flux Forms eklentisinin sürümüyle uyumlu değil.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to download files' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti dosyaları indiremiyor',
  'Cannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.' => 'Eklentiler kurulamıyor çünkü bu sunucu, indirmeyi hazırlamak için gereken PHP dosya sistemi işlevlerini devre dışı bırakmış. Lütfen barındırma sağlayıcınızdan mkdir ve rename işlevlerini etkinleştirmesini isteyin veya WordPress dosya sistemini yapılandırın.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti indirilen dosyayı taşıyamıyor',
  'Cannot install add-ons of Flux Forms because the plugin is not able to unzip files' => 'Flux Forms eklentileri kurulamıyor çünkü eklenti zip dosyalarını açamıyor',
  'To fix this, sign in to your %s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.' => 'Bunu düzeltmek için %s hesabınızda oturum açın, İndirmeler bölümünden Add-ons Handler eklentisini indirin, ardından kurup etkinleştirin. Sonra ihtiyacınız olan eklentileri Add-ons Handler eklentisinden etkinleştirin.',
  'WhiteStudio dashboard' => 'WhiteStudio dashboard',
  'This bundled add-on is missing from the plugin files.' => 'Bu pakete dahil eklenti, eklenti dosyalarında eksik.',
  'The add-on server returned an unexpected response.' => 'Eklenti sunucusu beklenmeyen bir yanıt döndürdü.',
  'The add-on could not be installed.' => 'Eklenti yüklenemedi.',
  'The add-on server did not provide a download URL.' => 'Eklenti sunucusu bir indirme URL\'si sağlamadı.',
  'The add-on download URL is not an approved Flux Forms source.' => 'Eklenti indirme URL\'si onaylı bir Flux Forms kaynağı değil.',
  'Your server could not reach %1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at %2$s and download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.' => 'Sunucunuz %1$s adresine ulaşamadığı için eklenti indirilemedi. Bu hemen hemen her zaman lisansınızla ilgili bir sorun değil, barındırmanızdaki bir güvenlik duvarının giden isteği engellemesidir. Eklentileri hiç indirmeden yüklemek için %2$s adresinde oturum açın, Flux Forms Add-ons Handler eklentisini indirin ve diğer eklentiler gibi yükleyin. Lisansınızın kapsadığı tüm eklentileri içerir.',
  'If you would rather fix the connection, ask your hosting provider why outgoing requests from %s are being blocked.' => 'Bağlantıyı düzeltmeyi tercih ederseniz, barındırma sağlayıcınıza %s adresinden giden isteklerin neden engellendiğini sorun.',
  'Flux Forms: add-on downloads are being blocked' => 'Flux Forms: eklenti indirmeleri engelleniyor',
  'Add-on affected: %s' => 'Etkilenen eklenti: %s',
  'No response was recorded for this add-on.' => 'Bu eklenti için kayıtlı bir yanıt yok.',
  'Writable' => 'Yazılabilir',
  'Not writable — the add-on folder cannot be created or extracted into.' => 'Yazılamaz — eklenti klasörü oluşturulamıyor veya içine çıkarma yapılamıyor.',
  'Blocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.' => 'WP_HTTP_BLOCK_EXTERNAL tarafından engellendi — bu sitede giden istekler devre dışı.',
  'DISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.' => 'DISABLE_WP_CRON açık — arka plan yeniden denemeleri yalnızca bir sunucu cron görevi wp-cron.php\'yi çağırırsa çalışır.',
  'Page that needed it' => 'Gerektiren sayfa',
  'Plugin version' => 'Eklenti sürümü',
  'Add-on folder' => 'Eklenti klasörü',
  'Outgoing requests' => 'Giden istekler',
  'WP-Cron' => 'WP-Cron',
  'Attempts made' => 'Yapılan deneme sayısı',
  'Flux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.' => 'Flux Forms, eklenti dosyalarını otomatik olarak yeniden yükleyemedi. Bu eklentilere dayanan formlar, sorun çözülene kadar ziyaretçilere geçici bir mesaj gösteriyor.',
  'What is missing' => 'Neler eksik',
  'Diagnostics' => 'Tanılama',
  'What to do next' => 'Sonraki adım',
  'Open Flux Forms in your dashboard and use the Recover add-ons button.' => 'Dashboard\'unuzda Flux Forms\'u açın ve Eklentileri kurtar düğmesini kullanın.',
  'If the add-on folder is not writable, ask your host to allow writing to the plugin folder.' => 'Eklenti klasörü yazılabilir değilse, barındırma sağlayıcınızdan eklenti klasörüne yazmaya izin vermesini isteyin.',
  'If outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.' => 'Giden istekler engelleniyorsa, barındırma sağlayıcınızdan Flux Forms güncelleme sunucusuna bağlantılara izin vermesini isteyin.',
  'If your Pro subscription has expired, renew it to restore the Pro add-ons.' => 'Pro aboneliğinizin süresi dolduysa, Pro eklentilerini geri yüklemek için yenileyin.',
  'We have made some updates. Please wait a few minutes before trying again.' => 'Bazı güncellemeler yaptık. Lütfen tekrar denemeden önce birkaç dakika bekleyin.',
  'Cannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server' => 'Flux Forms eklentileri yüklenemiyor çünkü eklenti whitestudio.team sunucusuna bağlanamıyor',
  'One of the free features' => 'Ücretsiz özelliklerden biri',
  'Important: Caching Plugin May Affect Flux Forms' => 'Önemli: Önbellek Eklentisi Flux Forms\'u Etkileyebilir',
  'The following caching plugins are active on your site:' => 'Sitenizde aşağıdaki önbellek eklentileri etkin:',
  'Plugin Name' => 'Eklenti Adı',
  'Slug' => 'Slug',
  'Please note that these plugins may affect the functionality of Flux Forms.' => 'Bu eklentilerin Flux Forms\'un işleyişini etkileyebileceğini unutmayın.',
  'If you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.' => 'Herhangi bir sorun yaşarsanız, formunuzun yayınlandığı sayfayı önbellekten hariç tutun veya bu eklentileri devre dışı bırakın. Bu hariç tutmanın nasıl ayarlanacağına dair ayrıntılı bilgi için ilgili önbellek eklentisinin belgelerine bakın.',
  'Sent by' => 'Gönderen',
  'Action needed: Flux Forms Pro is paused on %s' => 'İşlem gerekli: Flux Forms Pro, %s sitesinde duraklatıldı',
  'Flux Forms could not confirm your Pro licence for %1$s days in a row, so the Pro features on %2$s are paused for now.' => 'Flux Forms, %1$s gün üst üste Pro lisansınızı doğrulayamadı; bu nedenle %2$s sitesindeki Pro özellikleri şimdilik duraklatıldı.',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored &mdash; nothing was deleted.' => 'Formlarınıza, girdilerinize ve ayarlarınıza dokunulmadı, tüm ücretsiz özellikler çalışmaya devam ediyor ve etkinleştirme kodunuz hâlâ saklanıyor &mdash; hiçbir şey silinmedi.',
  'Open %1$sYT Form &rarr; Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => '%1$sYT Form &rarr; Ayarlar%2$s sayfasını açın ve %1$sKaydet%2$s düğmesine basın. Bu, lisansı hemen yeniden kontrol eder; bağlantı geri geldiyse Pro bir dakika içinde açılır.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s &mdash; a firewall, proxy or regional block is the usual cause &mdash; then repeat step 1.' => 'Hâlâ duraklatılmış mı? Barındırma sağlayıcınızdan %s adresine giden HTTPS bağlantılarına izin vermesini isteyin &mdash; genellikle nedeni bir güvenlik duvarı, proxy veya bölgesel engeldir &mdash; ardından 1. adımı tekrarlayın.',
  'If your subscription has expired, or you moved this website to a new domain, %1$srenew or re-activate your licence%2$s and paste the new code into Settings.' => 'Aboneliğinizin süresi dolduysa veya bu web sitesini yeni bir alan adına taşıdıysanız, %1$slisansınızı yenileyin veya yeniden etkinleştirin%2$s ve yeni kodu Ayarlar\'a yapıştırın.',
  'First failed check' => 'İlk başarısız kontrol',
  'Grace period' => 'Ek süre',
  'Activation code' => 'Etkinleştirme kodu',
  'Error code' => 'Hata kodu',
  'How to bring Pro back' => 'Pro nasıl geri getirilir',
  'Check my licence now' => 'Lisansımı şimdi kontrol et',
  'Still stuck? Send the details above to %1$sour support team%2$s and we will take it from there.' => 'Hâlâ çözemediniz mi? Yukarıdaki ayrıntıları %1$sdestek ekibimize%2$s gönderin, gerisini biz hallederiz.',
  'The licence server answered with an error and could not confirm your licence.' => 'Lisans sunucusu bir hatayla yanıt verdi ve lisansınızı doğrulayamadı.',
  'Your website could not reach the licence server &mdash; almost always a network, firewall or DNS restriction on the hosting side.' => 'Web siteniz lisans sunucusuna ulaşamadı &mdash; neredeyse her zaman barındırma tarafındaki bir ağ, güvenlik duvarı veya DNS kısıtlamasıdır.',
  'The licence server&rsquo;s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'Lisans sunucusu&rsquo;nun yanıtı bozuk ulaştı; genellikle bir güvenlik eklentisi, proxy veya CDN onu yolda değiştirmiştir.',
  'The licence check could not be completed.' => 'Lisans kontrolü tamamlanamadı.',
  'Your activation code has expired!' => 'Etkinleştirme kodunuzun süresi doldu!',
  'Your Easy Form Builder Pro subscription has expired. To continue using the %s add-on and all Pro features, please renew your subscription.' => 'Flux Forms Pro aboneliğinizin süresi doldu. %s eklentisini ve tüm Pro özelliklerini kullanmaya devam etmek için lütfen aboneliğinizi yenileyin.',
  'Renew Subscription' => 'Aboneliği Yenile',
  'Pro Version Required' => 'Pro Sürüm Gerekli',
  'The %s add-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.' => '%s eklentisi bir Pro özelliğidir. Bu işlevselliğe erişmek için lütfen Flux Forms Pro\'ya yükseltin.',
  'Your Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running, %1$sRenew your subscription now.%2$s' => 'Flux Forms Pro aboneliğinizin süresi doldu. Tüm Pro özelliklerinin keyfini çıkarmaya devam etmek ve formlarınızı çalışır durumda tutmak için %1$sAboneliğinizi şimdi yenileyin.%2$s',
