  'Flux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.' => 'Flux Forms yüklemeleri zaten kendisi sınırlar: her ziyaretçi formdaki her dosya alanı için üç dosya yükleyebilir, yanıt kutusu da üç dosyaya izin verir. Bu otomatik davranışı korumak için kutuyu 0 bırakın veya kendiniz ayarlamak için bir sayı girin.',
  'Uploads allowed per file field' => 'Dosya alanı başına izin verilen yükleme',
  'Default 3, so a two-field form allows six uploads. 0 keeps the default.' => 'Varsayılan 3, yani iki alanlı bir form altı yüklemeye izin verir. 0 varsayılanı korur.',
  'Total uploads per visitor' => 'Ziyaretçi başına toplam yükleme',
  'A fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.' => 'Formda kaç alan olduğuna bakmayan sabit bir toplam. 0 otomatik alan başı hesaplamayı korur.',
  'Budget resets after (seconds)' => 'Bütçe şu süre sonra sıfırlanır (saniye)',
  'Default 3600 (one hour). 0 keeps the default.' => 'Varsayılan 3600 (bir saat). 0 varsayılanı korur.',
  'Maximum file size (MB)' => 'Maksimum dosya boyutu (MB)',
  'A site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.' => 'Site genelinde bir üst sınır. Alan başına limiti yalnızca daraltabilir, asla genişletemez. 0 alan ayarını korur.',
  'Protect response lookup' => 'Yanıt sorgulamasını koru',
  'Rate-limit tracking-code searches by request count (no human-token check).' => 'Takip kodu aramalarını istek sayısına göre sınırlayın (insan token kontrolü yok).',
  'Manual access lists' => 'Manuel erişim listeleri',
  'One entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.' => 'Her satıra bir kayıt: tam bir IP veya 203.0.113.* gibi joker karakterli önek — izin listesi tüm kontrolleri atlar, engelleme listesi her modda engeller.',
  'IP allowlist' => 'IP izin listesi',
  'Trusted IPs that skip the shield completely (your office, monitoring bots).' => 'Korumayı tamamen atlayan güvenilir IP\'ler (ofisiniz, izleme botları).',
  'IP blocklist' => 'IP engelleme listesi',
  'IPs that are always blocked on protected form routes.' => 'Korumalı form yollarında her zaman engellenen IP\'ler.',
  'Minimum paid notification score' => 'Minimum ücretli bildirim puanı',
