  'Webhook/Email daily stop-loss' => 'Webhook/E-posta günlük zarar durdurma',
  'Global webhook/email/sheet budget per day.' => 'Günlük genel webhook/e-posta/e-tablo bütçesi.',
  'Per-recipient daily cap' => 'Alıcı başına günlük üst sınır',
  'Maximum notifications per single recipient per day (0 disables).' => 'Alıcı başına günlük en fazla bildirim sayısı (0 devre dışı bırakır).',
  'These limits become active for paid services after the core integration filter is added.' => 'Bu limitler, çekirdek entegrasyon filtresi eklendikten sonra ücretli hizmetler için etkin olur.',
