  'Trust proxy IP headers' => 'Proxy IP üstbilgilerine güven',
  'Use forwarding headers only when the immediate peer matches the trusted proxy list below.' => 'Yönlendirme üstbilgilerini yalnızca doğrudan bağlanan eş aşağıdaki güvenilir proxy listesiyle eşleştiğinde kullanın.',
  'Trusted proxy IPs' => 'Güvenilir proxy IP\'leri',
  'One exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.' => 'Her satıra tam bir IP veya joker karakterli önek. Yalnızca yük dengeleyici/CDN çıkış adreslerinizi ekleyin; kaynak sunucuya doğrudan erişilebiliyorsa boş bırakın.',
  'Store raw behavior metrics' => 'Ham davranış metriklerini sakla',
  'Keep off for privacy unless debugging a rollout.' => 'Bir yayına alma sorununu ayıklamıyorsanız gizlilik için kapalı tutun.',
