  'If a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.' => 'Gerekli bir PHP işlevi devre dışıysa php.ini içindeki disable_functions\'tan etkinleştirin veya barındırıcıdan izin vermesini isteyin. Önbellek ve güvenlik eklentileri /wp-json/EmsfbShield/v1/* adresinden gelen POST yanıtlarını önbelleğe almamalı veya yeniden yazmamalıdır.',
  'Security & Spam Protection tabs' => 'Güvenlik ve Spam Koruması sekmeleri',
  'Security log export is unavailable because this server has disabled a required PHP function: %s. Ask your hosting provider to enable it.' => 'Güvenlik günlüğü dışa aktarımı kullanılamıyor çünkü bu sunucu gerekli bir PHP işlevini devre dışı bırakmış: %s. Barındırma sağlayıcınızdan etkinleştirmesini isteyin.',
  'Security log export is unavailable because this server has disabled required PHP functions: %s. Ask your hosting provider to enable them.' => 'Güvenlik günlüğü dışa aktarımı kullanılamıyor çünkü bu sunucu gerekli PHP işlevlerini devre dışı bırakmış: %s. Barındırma sağlayıcınızdan etkinleştirmesini isteyin.',
