  'Automatically send form submissions to your Google Sheets. Connect one or more service accounts, link a sheet to each form, and let data flow in real time — no webhook or browser login required.' => 'Form gönderimlerini otomatik olarak Google E-Tablolar\'a gönderin. Bir veya daha fazla hizmet hesabı bağlayın, her forma bir tablo bağlayın ve verilerin gerçek zamanlı akmasını sağlayın — webhook veya tarayıcı girişi gerekmez.',
  'Not Connected' => 'Bağlı Değil',
  'Auto Sync' => 'Otomatik Senkronizasyon',
  'Auto Header' => 'Otomatik Başlık',
  'Sync Logs' => 'Senkronizasyon Günlükleri',
  'Google Sheet Settings' => 'Google E-Tablolar Ayarları',
  'Active Bindings' => 'Aktif Bağlantılar',
  'Form' . chr(0) . 'Forms' => 'formu' . chr(0) . 'Formlar',
  '%d service account connected' . chr(0) . '%d service accounts connected' => '%d hizmet hesabı bağlandı' . chr(0) . '%d hizmet hesapları bağlandı',
  'No service account connected yet' => 'Henüz bağlı hizmet hesabı yok',
  'Form Bindings' => 'Form Bağlantıları',
  'Help & Guide' => 'Yardım ve Kılavuz',
  'Saved successfully.' => 'Başarıyla kaydedildi.',
  'Open in Google Sheets' => 'Google E-Tablolar\'da Aç',
  'Service Accounts' => 'Hizmet Hesapları',
  'Connect one or more Google service accounts — no browser login required' => 'Bir veya daha fazla Google hizmet hesabı bağlayın — tarayıcı girişi gerekmez',
  'Your server is missing the PHP OpenSSL extension.' => 'Sunucunuzda PHP OpenSSL eklentisi eksik.',
  'Google Sheet sync cannot work until it is enabled. Please ask your host to enable the %s PHP extension, then reload this page.' => 'Etkinleştirilene kadar Google E-Tablolar senkronizasyonu çalışmaz. Lütfen hosting sağlayıcınızdan %s PHP eklentisini etkinleştirmesini isteyin, ardından bu sayfayı yeniden yükleyin.',
  'Copy this email' => 'Bu e-postayı kopyala',
  'Copy email' => 'E-postayı kopyala',
  'To sync an <strong>existing</strong> sheet: open it in Google Sheets &rarr; <strong>Share</strong> &rarr; paste the email above &rarr; set role to <strong>Editor</strong>. To create a <strong>new</strong> sheet, just use Form Bindings — no sharing needed.' => '<strong>Mevcut</strong> bir tabloyu senkronize etmek için: tabloyu Google E-Tablolar\'da açın &rarr; <strong>Paylaş</strong> &rarr; yukarıdaki e-postayı yapıştırın &rarr; rolü <strong>Düzenleyen</strong> yapın. <strong>Yeni</strong> bir tablo oluşturmak için Form Bağlantıları\'nı kullanmanız yeterli — paylaşım gerekmez.',
  'Set Default' => 'Varsayılan Yap',
  'Retest' => 'Yeniden Test Et',
  'Let’s connect Google Sheets — about 3 minutes, one time' => 'Google E-Tablolar\'ı bağlayalım — yaklaşık 3 dakika, tek seferlik',
  'Follow the numbered steps on the right to download a free service account key from Google, then drop the file below. You only do this once. After that, creating a sheet for any form is a couple of clicks.' => 'Google\'dan ücretsiz bir hizmet hesabı anahtarı indirmek için sağdaki numaralı adımları izleyin, ardından dosyayı aşağıya bırakın. Bunu yalnızca bir kez yaparsınız. Sonrasında herhangi bir form için tablo oluşturmak birkaç tıklama sürer.',
  'Your Google email' => 'Google e-postanız',
  '(recommended)' => '(önerilir)',
  'Any sheet the plugin <strong>creates</strong> is automatically shared to this address, so it appears in your own Google Drive under “Shared with me.” Without it, new sheets stay hidden inside the service account.' => 'Eklentinin <strong>oluşturduğu</strong> her tablo otomatik olarak bu adresle paylaşılır ve kendi Google Drive\'ınızda “Benimle paylaşılanlar” altında görünür. Bu adres olmadan yeni tablolar hizmet hesabının içinde gizli kalır.',
  'Enable Google Sheet Integration' => 'Google E-Tablolar Entegrasyonunu Etkinleştir',
  'Sync form submissions to your spreadsheets automatically' => 'Form gönderimlerini tablolarınızla otomatik senkronize edin',
  'Drag & drop service account JSON file(s) here' => 'Hizmet hesabı JSON dosyalarını buraya sürükleyip bırakın',
  'or click to browse — you can add multiple service accounts at once' => 'veya göz atmak için tıklayın — aynı anda birden fazla hizmet hesabı ekleyebilirsiniz',
  'Connected service accounts' => 'Bağlı hizmet hesapları',
  'One-time setup (≈3 min)' => 'Tek seferlik kurulum (≈3 dk)',
  'Go to <a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> &rarr; Project dropdown (top-left) &rarr; New Project &rarr; name it &rarr; Create' => '<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> adresine gidin &rarr; Proje açılır menüsü (sol üst) &rarr; Yeni Proje &rarr; bir ad verin &rarr; Oluştur',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> <em>and</em> <strong>Google Drive API</strong>' => 'APIs &amp; Services &rarr; Library &rarr; <strong>Google Sheets API</strong> <em>ve</em> <strong>Google Drive API</strong>\'yi etkinleştirin',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; name it &rarr; Done' => 'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; bir ad verin &rarr; Done',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; JSON (downloads automatically)' => 'Hizmet hesabını açın &rarr; Keys sekmesi &rarr; Add Key &rarr; Create New Key &rarr; JSON (otomatik iner)',
  'Drag that downloaded file into the box on the left — it is tested automatically' => 'İndirilen dosyayı soldaki kutuya sürükleyin — otomatik olarak test edilir',
  'Add <strong>Your Google email</strong> above so created sheets land in your Drive' => 'Oluşturulan tabloların Drive\'ınıza düşmesi için yukarıya <strong>Google e-postanızı</strong> ekleyin',
  'Please choose a valid .json key file.' => 'Lütfen geçerli bir .json anahtar dosyası seçin.',
  'Could not read file: %s' => 'Dosya okunamadı: %s',
  'Connecting service account…' => 'Hizmet hesabı bağlanıyor…',
  'Service account added.' => 'Hizmet hesabı eklendi.',
  'Saved. New sheets created by the plugin will be shared to %s automatically.' => 'Kaydedildi. Eklentinin oluşturduğu yeni tablolar otomatik olarak %s ile paylaşılacak.',
  'Email cleared. New sheets will stay inside the service account until you share them.' => 'E-posta temizlendi. Yeni tablolar, siz paylaşana kadar hizmet hesabının içinde kalacak.',
  'Remove this service account?' => 'Bu hizmet hesabı kaldırılsın mı?',
  'Testing connection…' => 'Bağlantı test ediliyor…',
  'Connect each form to a specific Google Sheet tab' => 'Her formu belirli bir Google E-Tablolar sekmesine bağlayın',
  'Connect each form to a specific Google Sheet tab — step by step' => 'Her formu belirli bir Google E-Tablolar sekmesine bağlayın — adım adım',
  'No service account connected.' => 'Bağlı hizmet hesabı yok.',
  'Go to the Connections tab and drop a service account JSON key first.' => 'Önce Bağlantılar sekmesine gidin ve bir hizmet hesabı JSON anahtarı bırakın.',
  'Last sync OK' => 'Son senkronizasyon başarılı',
  'Last sync failed' => 'Son senkronizasyon başarısız',
  'Remove sync? The sheet stays safe.' => 'Senkronizasyon kaldırılsın mı? Tablonuz güvende kalır.',
  'Yes, remove' => 'Evet, kaldır',
  'Remove this sync (your Google Sheet is not deleted)' => 'Bu senkronizasyonu kaldır (Google Tablonuz silinmez)',
  'Existing Bindings' => 'Mevcut Bağlantılar',
  'Delete All' => 'Tümünü Sil',
  'New Binding' => 'Yeni Bağlantı',
  'Spreadsheet ID' => 'Tablo Kimliği',
  'Tab' => 'Sekme',
  'Choose Sheet' => 'Tablo Seç',
  'Columns & Fields' => 'Sütunlar ve Alanlar',
  'Style & Save' => 'Stil ve Kaydet',
  'Which form should send data to Google Sheets?' => 'Hangi form verileri Google E-Tablolar\'a göndersin?',
  'Please select a form first.' => 'Lütfen önce bir form seçin.',
  'Service Account' => 'Hizmet Hesabı',
  'Loading your spreadsheets…' => 'Tablolarınız yükleniyor…',
  'Click <strong>“Browse My Sheets”</strong> to list spreadsheets this service account can already access, or <strong>“Create New Sheet”</strong> to make a fresh one.' => 'Bu hizmet hesabının erişebildiği tabloları listelemek için <strong>“Tablolarıma Göz At”</strong>a, yeni bir tablo oluşturmak için <strong>“Yeni Tablo Oluştur”</strong>a tıklayın.',
  '<strong>No spreadsheets are accessible to this service account yet.</strong> You have two options:' => '<strong>Bu hizmet hesabının erişebildiği tablo henüz yok.</strong> İki seçeneğiniz var:',
  '<strong>Easiest:</strong> click <em>“Create New Sheet”</em> above — it is made for you and shared to your email automatically.' => '<strong>En kolayı:</strong> yukarıdaki <em>“Yeni Tablo Oluştur”</em>a tıklayın — sizin için oluşturulur ve e-postanızla otomatik paylaşılır.',
  '<strong>Use an existing sheet:</strong> open it in Google Sheets &rarr; Share &rarr; paste' => '<strong>Mevcut bir tabloyu kullanın:</strong> Google E-Tablolar\'da açın &rarr; Paylaş &rarr; şunu yapıştırın:',
  '&rarr; Editor, then click <em>Browse My Sheets</em> again.' => '&rarr; Düzenleyen yapın, ardından <em>Tablolarıma Göz At</em>\'a tekrar tıklayın.',
  'the service account email' => 'hizmet hesabı e-postası',
  'Create a new spreadsheet' => 'Yeni bir tablo oluştur',
  'New spreadsheet title (e.g. Contact form responses)' => 'Yeni tablo başlığı (örn. İletişim formu yanıtları)',
  'Your Google email — the sheet is shared here so you can open it' => 'Google e-postanız — tablo, açabilmeniz için buraya paylaşılır',
  'Pre-filled from your saved email.' => 'Kayıtlı e-postanızdan önceden dolduruldu.',
  'Leave empty only if you don’t need to open the sheet yourself.' => 'Tabloyu kendiniz açmanız gerekmiyorsa boş bırakın.',
  'Create Sheet' => 'Tablo Oluştur',
  'Creating…' => 'Oluşturuluyor…',
  'Creating spreadsheet…' => 'Tablo oluşturuluyor…',
  'Sheet created and shared with your email. It’s selected below — click Next to finish.' => 'Tablo oluşturuldu ve e-postanızla paylaşıldı. Aşağıda seçili — bitirmek için İleri\'ye tıklayın.',
  'Sheet created. Tip: add “Your Google email” on the Connections tab so new sheets are shared to you automatically.' => 'Tablo oluşturuldu. İpucu: yeni tabloların size otomatik paylaşılması için Bağlantılar sekmesine “Google e-postanızı” ekleyin.',
  'Open the new sheet' => 'Yeni tabloyu aç',
  'Selected:' => 'Seçili:',
  'Loading worksheet tabs…' => 'Çalışma sayfası sekmeleri yükleniyor…',
  'Worksheet Tab' => 'Çalışma Sayfası Sekmesi',
  'Or type a new tab name (created automatically)' => 'Veya yeni bir sekme adı yazın (otomatik oluşturulur)',
  'Browse My Sheets' => 'Tablolarıma Göz At',
  'Create New Sheet' => 'Yeni Tablo Oluştur',
  'Choose or create a spreadsheet first' => 'Önce bir tablo seçin veya oluşturun',
  'Please select a service account.' => 'Lütfen bir hizmet hesabı seçin.',
  'Please choose or create a spreadsheet first.' => 'Lütfen önce bir tablo seçin veya oluşturun.',
  'Enable Sync for this Form' => 'Bu Form İçin Senkronizasyonu Etkinleştir',
  'Disable to pause without deleting the binding' => 'Bağlantıyı silmeden duraklatmak için devre dışı bırakın',
  'Reading this form’s fields…' => 'Bu formun alanları okunuyor…',
  'We couldn’t read this form’s fields automatically, so column mapping isn’t available. Don’t worry — <strong>every submitted field will still be synced automatically</strong>, each in its own column, in submission order. The header row is created and kept up to date for you.' => 'Bu formun alanlarını otomatik okuyamadık, bu nedenle sütun eşleme kullanılamıyor. Endişelenmeyin — <strong>gönderilen her alan yine de otomatik olarak senkronize edilir</strong>; her biri kendi sütununda, gönderim sırasına göre yer alır. Başlık satırı sizin için oluşturulur ve güncel tutulur.',
  'Drag rows (or use ▲▼) to set the <strong>column order</strong>. Rename any <strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C…) shows where each field lands.' => '<strong>Sütun sırasını</strong> belirlemek için satırları sürükleyin (veya ▲▼ kullanın). İstediğiniz <strong>başlığı</strong> yeniden adlandırın. Bir alanın sütununu atlamak için alanı kapatın. Harf (A, B, C…) her alanın nereye düştüğünü gösterir.',
  'Col' => 'Sütun',
  'Spreadsheet header' => 'Tablo başlığı',
  'Order / On' => 'Sıra / Açık',
  'Refresh fields from form' => 'Alanları formdan yenile',
  'Columns & Field Mapping' => 'Sütunlar ve Alan Eşleme',
  'Submitted time' => 'Gönderim zamanı',
  'Submitted At' => 'Gönderim Zamanı',
  'Column header' => 'Sütun başlığı',
  'Include this field' => 'Bu alanı dahil et',
  '%d column will be written to the sheet.' . chr(0) . '%d columns will be written to the sheet.' => 'Sayfaya %d sütunu yazılacaktır.' . chr(0) . '%d sütunları sayfaya yazılacaktır.',
  'Sheet Style' => 'Tablo Stili',
  '(Google theme)' => '(Google teması)',
  'Pick a look for the sheet — colored header, frozen top row and alternating row colors (Google Sheets’ own styling). It’s applied automatically on the first sync, or apply it now.' => 'Tablo için bir görünüm seçin — renkli başlık, sabitlenmiş üst satır ve dönüşümlü satır renkleri (Google E-Tablolar\'ın kendi stili). İlk senkronizasyonda otomatik uygulanır veya şimdi uygulayabilirsiniz.',
  'Apply style now' => 'Stili şimdi uygula',
  'Applying…' => 'Uygulanıyor…',
  'Optional — it also applies on the first submission.' => 'İsteğe bağlı — ilk gönderimde de uygulanır.',
  'Spreadsheet:' => 'Tablo:',
  'Tab:' => 'Sekme:',
  'Columns:' => 'Sütunlar:',
  '%d mapped' => '%d eşlendi',
  'all submitted fields (auto)' => 'gönderilen tüm alanlar (otomatik)',
  'Style:' => 'Stil:',
  'After saving, submit the form once to create the header row and confirm the first sync.' => 'Kaydettikten sonra başlık satırını oluşturmak ve ilk senkronizasyonu doğrulamak için formu bir kez gönderin.',
  'Save Binding' => 'Bağlantıyı Kaydet',
  'Please choose a spreadsheet first.' => 'Lütfen önce bir tablo seçin.',
  'Pick a style first — “None” leaves the sheet unstyled.' => 'Önce bir stil seçin — “Yok” tabloyu stilsiz bırakır.',
  'Style applied.' => 'Stil uygulandı.',
  'Please select a form.' => 'Lütfen bir form seçin.',
  'Please choose a spreadsheet.' => 'Lütfen bir tablo seçin.',
  'Binding saved.' => 'Bağlantı kaydedildi.',
  'Remove this binding? Syncing stops for this form. Your Google Sheet and its data are not deleted.' => 'Bu bağlantı kaldırılsın mı? Bu form için senkronizasyon durur. Google Tablonuz ve verileri silinmez.',
  'Sync removed — your Google Sheet and its data are untouched.' => 'Senkronizasyon kaldırıldı — Google Tablonuza ve verilerine dokunulmadı.',
  'Remove ALL %d binding? Syncing stops for every form. Your Google Sheets are not deleted.' . chr(0) . 'Remove ALL %d bindings? Syncing stops for every form. Your Google Sheets are not deleted.' => 'TÜM %d bağlaması kaldırılsın mı? Her form için senkronizasyon durakları. Google E-Tablolarınız silinmez.' . chr(0) . 'TÜM %d bağlamaları kaldırılsın mı? Her form için senkronizasyon durakları. Google E-Tablolarınız silinmez.',
  'All bindings removed. Your Google Sheets are untouched.' => 'Tüm bağlantılar kaldırıldı. Google Tablolarınıza dokunulmadı.',
  'Help & Setup Guide' => 'Yardım ve Kurulum Kılavuzu',
  'Everything you need to connect forms to Google Sheets' => 'Formları Google E-Tablolar\'a bağlamak için ihtiyacınız olan her şey',
  'Step-by-Step Setup' => 'Adım Adım Kurulum',
  'Create or Select a Project' => 'Proje Oluşturun veya Seçin',
  'Open console.cloud.google.com and log in &rarr; click the Project dropdown (top-left) &rarr; New Project (or pick an existing one) &rarr; enter a name &rarr; Create' => 'console.cloud.google.com adresini açıp giriş yapın &rarr; Proje açılır menüsüne (sol üst) tıklayın &rarr; Yeni Proje (veya mevcut birini seçin) &rarr; bir ad girin &rarr; Oluştur',
  'Enable both Google APIs' => 'Her iki Google API\'sini etkinleştirin',
  'APIs &amp; Services &rarr; Library &rarr; enable <strong>Google Sheets API</strong> and <strong>Google Drive API</strong> (both are required — Drive lists and creates the files)' => 'APIs &amp; Services &rarr; Library &rarr; <strong>Google Sheets API</strong> ve <strong>Google Drive API</strong>\'yi etkinleştirin (ikisi de gereklidir — Drive dosyaları listeler ve oluşturur)',
  'Create a Service Account' => 'Hizmet Hesabı Oluşturun',
  'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; enter a name &rarr; Done' => 'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; bir ad girin &rarr; Done',
  'Create a JSON Key' => 'JSON Anahtarı Oluşturun',
  'Open the service account &rarr; Keys tab &rarr; Add Key &rarr; Create New Key &rarr; choose JSON (file downloads automatically)' => 'Hizmet hesabını açın &rarr; Keys sekmesi &rarr; Add Key &rarr; Create New Key &rarr; JSON\'u seçin (dosya otomatik iner)',
  'Drop the Key File' => 'Anahtar Dosyasını Bırakın',
  'Drag the downloaded file into the Connections tab — it is verified automatically and you’ll see a green “Connected” badge' => 'İndirilen dosyayı Bağlantılar sekmesine sürükleyin — otomatik doğrulanır ve yeşil bir “Bağlı” rozeti görürsünüz',
  'Add Your Google Email' => 'Google E-postanızı Ekleyin',
  'On the Connections tab, fill in “Your Google email” and Save — sheets the plugin creates are then shared to you so they appear in your own Drive' => 'Bağlantılar sekmesinde “Google e-postanız” alanını doldurup Kaydedin — eklentinin oluşturduğu tablolar size paylaşılır ve kendi Drive\'ınızda görünür',
  'Bind a Form (create a sheet)' => 'Bir Formu Bağlayın (tablo oluşturun)',
  'Form Bindings &rarr; pick a form &rarr; <strong>Create New Sheet</strong> &rarr; Save. No manual sharing needed — this is the easiest path' => 'Form Bağlantıları &rarr; bir form seçin &rarr; <strong>Yeni Tablo Oluştur</strong> &rarr; Kaydet. Elle paylaşım gerekmez — en kolay yol budur',
  '…or use an existing sheet' => '…veya mevcut bir tabloyu kullanın',
  'Prefer your own sheet? Open it &rarr; Share &rarr; paste the service account email (copy button on its card) &rarr; Editor &rarr; then Browse My Sheets in the wizard' => 'Kendi tablonuzu mu tercih ediyorsunuz? Açın &rarr; Paylaş &rarr; hizmet hesabı e-postasını yapıştırın (kartındaki kopyala düğmesi) &rarr; Düzenleyen &rarr; ardından sihirbazda Tablolarıma Göz At\'ı kullanın',
  'I created a sheet — where did it go?' => 'Bir tablo oluşturdum — nereye gitti?',
  'Service accounts create files in their own hidden Drive. Add “Your Google email” on the Connections tab and the plugin shares every new sheet to you automatically — it then appears under “Shared with me” in your Google Drive. Each sheet also has an “Open” link right in this dashboard.' => 'Hizmet hesapları dosyaları kendi gizli Drive\'larında oluşturur. Bağlantılar sekmesine “Google e-postanızı” ekleyin; eklenti her yeni tabloyu size otomatik paylaşır ve Google Drive\'ınızda “Benimle paylaşılanlar” altında görünür. Her tablonun bu panelde ayrıca bir “Aç” bağlantısı da vardır.',
  'Why don’t I see my existing sheet in the picker?' => 'Mevcut tablom neden seçicide görünmüyor?',
  'It must be shared with the service account’s email first: open the sheet &rarr; Share &rarr; paste the email (use the copy button on the connection card) &rarr; set Editor &rarr; Share. Then click “Browse My Sheets” again.' => 'Önce hizmet hesabının e-postasıyla paylaşılmalıdır: tabloyu açın &rarr; Paylaş &rarr; e-postayı yapıştırın (bağlantı kartındaki kopyala düğmesini kullanın) &rarr; Düzenleyen yapın &rarr; Paylaş. Ardından “Tablolarıma Göz At”a tekrar tıklayın.',
  'Test result: Google API is not enabled.' => 'Test sonucu: Google API etkin değil.',
  'Open Google Cloud Console for the same project &rarr; APIs &amp; Services &rarr; Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'Aynı proje için Google Cloud Console\'u açın &rarr; APIs &amp; Services &rarr; Library ve HEM “Google Sheets API” HEM DE “Google Drive API”yi etkinleştirin. Bir dakika bekleyin, ardından tekrar test edin.',
  'Test result: Access/Permission denied' => 'Test sonucu: Erişim/İzin reddedildi',
  'The service account can authenticate but can’t reach that specific spreadsheet. Re-share the sheet with the service account email as Editor, or create a new sheet instead.' => 'Hizmet hesabı kimlik doğrulaması yapabiliyor ancak ilgili tabloya erişemiyor. Tabloyu hizmet hesabı e-postasıyla Düzenleyen olarak yeniden paylaşın veya bunun yerine yeni bir tablo oluşturun.',
  'OpenSSL is required.' => 'OpenSSL gereklidir.',
  'The server is missing the PHP OpenSSL extension used to sign the secure Google request. Ask your host to enable it — no plugin setting can replace it.' => 'Sunucuda, güvenli Google isteğini imzalamak için kullanılan PHP OpenSSL eklentisi eksik. Hosting sağlayıcınızdan etkinleştirmesini isteyin — hiçbir eklenti ayarı bunun yerini tutamaz.',
  'Can I connect more than one service account?' => 'Birden fazla hizmet hesabı bağlayabilir miyim?',
  'Yes — drop as many JSON keys as you like in the Connections tab and pick which one each form binding should use.' => 'Evet — Bağlantılar sekmesine istediğiniz kadar JSON anahtarı bırakın ve her form bağlantısının hangisini kullanacağını seçin.',
  'Does the connection expire?' => 'Bağlantının süresi dolar mı?',
  'No. The integration runs entirely on the server using your JSON key — there’s no browser session or login to expire.' => 'Hayır. Entegrasyon tamamen sunucuda JSON anahtarınızla çalışır — süresi dolacak bir tarayıcı oturumu veya giriş yoktur.',
  'Can I choose which field goes to which column?' => 'Hangi alanın hangi sütuna gideceğini seçebilir miyim?',
  'Yes. In the binding wizard’s <strong>Columns &amp; Fields</strong> step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'Evet. Bağlantı sihirbazının <strong>Sütunlar &amp; Alanlar</strong> adımında satırları sürükleyerek (veya ▲▼ kullanarak) sırayı belirleyin, her sütun başlığını yeniden adlandırın ve atlamak istediğiniz alanı kapatın. A/B/C rozeti her alanın tam olarak nereye düştüğünü gösterir.',
  'Can I style the sheet automatically?' => 'Tabloyu otomatik olarak biçimlendirebilir miyim?',
  'Yes. The <strong>Style &amp; Save</strong> step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'Evet. <strong>Stil &amp; Kaydet</strong> adımı Google E-Tablolar temaları sunar (renkli başlık, sabitlenmiş üst satır, dönüşümlü satır renkleri). Birini seçin; ilk senkronizasyonda uygulanır veya “Stili şimdi uygula”ya tıklayın.',
  'What if my form fields change later?' => 'Form alanlarım daha sonra değişirse ne olur?',
  'New fields are added automatically. In mapped mode, open the Columns step and click “Refresh fields from form” to pull them into the mapping; in “All Form Fields” mode they appear as new columns on the next submission.' => 'Yeni alanlar otomatik eklenir. Eşlemeli modda, Sütunlar adımını açıp “Alanları formdan yenile”ye tıklayarak bunları eşlemeye alın; “Tüm Form Alanları” modunda ise sonraki gönderimde yeni sütun olarak görünürler.',
  'What if the tab doesn’t exist yet?' => 'Sekme henüz yoksa ne olur?',
  'It is created automatically the first time a submission is synced.' => 'Bir gönderim ilk senkronize edildiğinde otomatik olarak oluşturulur.',
  'Google Sheet Sync Logs' => 'Google E-Tablolar Senkronizasyon Günlükleri',
  'Latest submissions sent to Google Sheets, success or failure' => 'Google E-Tablolar\'a gönderilen son gönderimler, başarılı veya başarısız',
  'Log cleared.' => 'Günlük temizlendi.',
  'Clear Log' => 'Günlüğü Temizle',
  'Clear all logs?' => 'Tüm günlükler temizlensin mi?',
  'No sync activity yet.' => 'Henüz senkronizasyon etkinliği yok.',
  'Spreadsheet' => 'Tablo',
  'Synced' => 'Senkronize edildi',
  'None (plain)' => 'Yok (düz)',
  'Minimal' => 'Minimal',
  'Slate' => 'Arduvaz',
  'Sunset' => 'Gün batımı',
  'Grape' => 'Üzüm',
  '%s is currently unavailable.' => '%s şu anda kullanılamıyor.',
  'disabled in php.ini: %s' => 'php.ini\'de devre dışı: %s',
  'not provided by PHP or its required extension: %s' => 'PHP veya gerekli eklentisi tarafından sağlanmıyor: %s',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disable_functions in php.ini.' => 'Gerekli PHP işlevleri kullanılamadığı için %1$s çalışamıyor (%2$s). Hosting sağlayıcınızdan gerekli PHP eklentisini etkinleştirmesini isteyin veya listelenen işlevleri php.ini içindeki disable_functions değerinden kaldırın.',
  'This add-on is not included in Flux Forms.' => 'Bu eklenti Flux Forms\'a dahil değildir.',
  'Error: server (%s) responded with an invalid request. responded code : %s ' => 'Hata: sunucu (%s) geçersiz bir istekle yanıt verdi. Yanıt kodu: %s ',
  'Your Easy Form Builder Pro subscription has expired, so this add-on cannot be downloaded.' => 'Flux Forms Pro aboneliğinizin süresi doldu, bu nedenle bu eklenti indirilemiyor.',
  'Something went wrong, please refresh the page.' => 'Bir şeyler ters gitti, lütfen sayfayı yenileyin.',
  'The response attachment could not be verified. Please attach the file again.' => 'Yanıt eki doğrulanamadı. Lütfen dosyayı tekrar ekleyin.',
  'You do not have permission to update these settings.' => 'Bu ayarları güncelleme izniniz yok.',
  'Please enter a valid admin email address.' => 'Lütfen geçerli bir yönetici e-posta adresi girin.',
  'You do not have permission to complete setup.' => 'Kurulumu tamamlama izniniz yok.',
  'Invalid email address' => 'Geçersiz e-posta adresi',
  'Invalid sender email' => 'Geçersiz gönderen e-postası',
  'The sender email address is not valid.' => 'Gönderen e-posta adresi geçerli değil.',
  'Email tester service error' => 'E-posta test hizmeti hatası',
  'Could not start email test.' => 'E-posta testi başlatılamadı.',
  'Invalid service response' => 'Geçersiz hizmet yanıtı',
  'The email tester service returned an invalid response.' => 'E-posta test hizmeti geçersiz bir yanıt döndürdü.',
  'The message never left your website: WordPress reported an error while trying to send it. This is the one case where the fix really is on the WordPress or hosting side - usually an SMTP plugin, or PHP mail disabled by the host.' => 'Mesaj web sitenizden hiç çıkmadı: WordPress göndermeye çalışırken bir hata bildirdi. Çözümün gerçekten WordPress veya barındırma tarafında olduğu tek durum budur - genellikle bir SMTP eklentisi veya barındırma firmasının devre dışı bıraktığı PHP mail.',
  'WordPress could not send the test email. The message never left your website, so nothing was delivered.' => 'WordPress test e-postasını gönderemedi. Mesaj web sitenizden hiç çıkmadığı için hiçbir şey teslim edilmedi.',
  'Email test is waiting for delivery confirmation' => 'E-posta testi teslim onayı bekliyor',
  'WordPress sent the test email. Flux Forms is waiting for the delivery result before marking email as ready.' => 'WordPress test e-postasını gönderdi. Flux Forms, e-postayı hazır olarak işaretlemeden önce teslim sonucunu bekliyor.',
  'WordPress accepted and sent the test email. Waiting for it to arrive.' => 'WordPress test e-postasını kabul etti ve gönderdi. Ulaşması bekleniyor.',
  'The email tester service returned an invalid JSON response.' => 'E-posta test hizmeti geçersiz bir JSON yanıtı döndürdü.',
  'The email tester service could not start the test.' => 'E-posta test hizmeti testi başlatamadı.',
  'Invalid test hash' => 'Geçersiz test karması',
  'The email test hash is not valid.' => 'E-posta testi karması geçerli değil.',
  'Your site could not connect' => 'Siteniz bağlanamadı',
  'No connection could be opened from your site to our mail testing service. This is usually outbound traffic blocked by your server or its network - some hosts block connections to other countries - rather than a problem with the service. Your hosting provider can confirm it.' => 'Sitenizden posta test hizmetimize hiçbir bağlantı açılamadı. Bu genellikle hizmetteki bir sorundan değil, sunucunuz veya ağı tarafından engellenen giden trafikten kaynaklanır - bazı barındırıcılar diğer ülkelere yapılan bağlantıları engeller. Barındırma sağlayıcınız bunu doğrulayabilir.',
  'Service error' => 'Hizmet hatası',
  'The email tester service could not return the result.' => 'E-posta test hizmeti sonucu döndüremedi.',
  'The message never left your website. WordPress reported an error while sending, so nothing could be delivered.' => 'Mesaj web sitenizden hiç çıkmadı. WordPress gönderirken bir hata bildirdi, bu nedenle hiçbir şey teslim edilemedi.',
  'The email was sent, but it never arrived' => 'E-posta gönderildi ama hiç ulaşmadı',
  'WordPress sent the message successfully, so your site and this plugin did their part. It was lost, delayed or rejected after leaving WordPress - usually the receiving side treated it as spam, or your host never delivered it from the outbound queue.' => 'WordPress mesajı başarıyla gönderdi, yani siteniz ve bu eklenti üzerine düşeni yaptı. Mesaj WordPress\'ten çıktıktan sonra kayboldu, gecikti veya reddedildi - genellikle alıcı taraf onu spam olarak değerlendirdi veya barındırıcınız giden kuyruktan hiç teslim etmedi.',
  'Email test failed' => 'E-posta testi başarısız',
  'The email server test could not verify email capability.' => 'E-posta sunucusu testi e-posta gönderme yeteneğini doğrulayamadı.',
  'Email capability verified' => 'E-posta yeteneği doğrulandı',
  'Server confirmed ability to send emails.' => 'Sunucu e-posta gönderebildiğini doğruladı.',
  'Your emails are being delivered to spam' => 'E-postalarınız spam klasörüne düşüyor',
  'WordPress sent the test email, but delivery has not been confirmed yet.' => 'WordPress test e-postasını gönderdi ancak teslimat henüz doğrulanmadı.',
  'Email delivery failed: %s' => 'E-posta teslimi başarısız: %s',
  'No file was received. Please choose a file and try again.' => 'Dosya alınamadı. Lütfen bir dosya seçip tekrar deneyin.',
  'The file could not be read. Please try attaching it again.' => 'Dosya okunamadı. Lütfen tekrar eklemeyi deneyin.',
  'Enable the Email Notification Feature' => 'E-posta Bildirimi Özelliğini Etkinleştirin',
  'To receive email notifications from your forms, verify your email server by following these steps:' => 'Formlarınızdan e-posta bildirimi almak için e-posta sunucunuzu şu adımları izleyerek doğrulayın:',
  'Go to the <a href="%s" style="font-weight:600;">Flux Forms Panel</a>' => '<a href="%s" style="font-weight:600;">Flux Forms Paneli</a>\'ne gidin',
  'Click Settings from the top menu' => 'Üst menüden Ayarlar\'a tıklayın',
  'Select the Email Settings tab' => 'E-posta Ayarları sekmesini seçin',
  'Click "Check Email Server" and wait for the test to finish' => '"E-posta Sunucusunu Kontrol Et"e tıklayın ve testin bitmesini bekleyin',
  'If the score is above 70 — enable the "This site can send emails" switch and save' => 'Puan 70\'in üzerindeyse "Bu site e-posta gönderebilir" anahtarını etkinleştirip kaydedin',
  'Otherwise, follow the instructions shown in the test results' => 'Aksi halde test sonuçlarında gösterilen yönergeleri izleyin',
  '%s notification' => '%s bildirimi',
  'Disabling this feature may affect the proper functionality of Flux Forms. If you plan to use the %s feature, please ensure it is enabled.' => 'Bu özelliği devre dışı bırakmak Flux Forms\'un düzgün çalışmasını etkileyebilir. %s özelliğini kullanmayı planlıyorsanız lütfen etkin olduğundan emin olun.',
  'Email system is working properly.' => 'E-posta sistemi düzgün çalışıyor.',
  'Your server is able to send emails using the default PHP mail system.' => 'Sunucunuz varsayılan PHP posta sistemini kullanarak e-posta gönderebiliyor.',
  'Email system is not available.' => 'E-posta sistemi kullanılamıyor.',
  'The PHP mail() function is missing. Your server cannot send emails.' => 'PHP mail() işlevi eksik. Sunucunuz e-posta gönderemez.',
  'Email sending is blocked by server settings.' => 'E-posta gönderimi sunucu ayarları tarafından engelleniyor.',
  'The mail() function is disabled in your server PHP configuration (php.ini).' => 'mail() işlevi sunucunuzun PHP yapılandırmasında (php.ini) devre dışı.',
  'WordPress mail function not found.' => 'WordPress posta işlevi bulunamadı.',
  'The wp_mail() function is missing or not available. WordPress email features may be broken.' => 'wp_mail() işlevi eksik veya kullanılamıyor. WordPress e-posta özellikleri bozuk olabilir.',
  'No email handler configured.' => 'Yapılandırılmış e-posta işleyicisi yok.',
  'Your server has no SMTP host or sendmail path set. Emails may not be delivered.' => 'Sunucunuzda SMTP ana bilgisayarı veya sendmail yolu ayarlanmamış. E-postalar teslim edilmeyebilir.',
  'Test email could not be sent.' => 'Test e-postası gönderilemedi.',
  'It seems that your WordPress site could not send a test email. To manually test your email system, go to Flux Forms > Settings > Email Settings tab and click the "Check Email Server" button.' => 'WordPress sitenizin test e-postası gönderemediği görünüyor. E-posta sisteminizi elle test etmek için Flux Forms > Ayarlar > E-posta Ayarları sekmesine gidin ve "E-posta Sunucusunu Kontrol Et" düğmesine tıklayın.',
  'Invalid email address.' => 'Geçersiz e-posta adresi.',
  'Please enter a valid admin email address before testing email delivery.' => 'E-posta teslimini test etmeden önce lütfen geçerli bir yönetici e-posta adresi girin.',
  'Invalid sender email.' => 'Geçersiz gönderen e-postası.',
  'The sender email address is not valid. Please check your email settings.' => 'Gönderen e-posta adresi geçerli değil. Lütfen e-posta ayarlarınızı kontrol edin.',
  'Email tester service error.' => 'E-posta test hizmeti hatası.',
  'Flux Forms could not start the email delivery test. Please try again later.' => 'Flux Forms e-posta teslim testini başlatamadı. Lütfen daha sonra tekrar deneyin.',
  'Invalid email tester response.' => 'Geçersiz e-posta test hizmeti yanıtı.',
  'Invalid email test.' => 'Geçersiz e-posta testi.',
  'The email test identifier is invalid. Please start a new test.' => 'E-posta testi tanımlayıcısı geçersiz. Lütfen yeni bir test başlatın.',
  'Email tester connection error.' => 'E-posta test hizmeti bağlantı hatası.',
  'Flux Forms could not connect to the email tester service.' => 'Flux Forms e-posta test hizmetine bağlanamadı.',
  'Email delivery test failed.' => 'E-posta teslim testi başarısız oldu.',
  'Your emails are arriving in the spam folder.' => 'E-postalarınız spam klasörüne düşüyor.',
  'The test message was delivered, but its deliverability score is too low to rely on. Sending through SMTP and adding SPF and DKIM records for your domain is what fixes this.' => 'Test mesajı teslim edildi ancak teslim edilebilirlik puanı güvenilmeyecek kadar düşük. Bunu düzeltmek için SMTP üzerinden gönderim yapın ve alan adınıza SPF ve DKIM kayıtları ekleyin.',
  'Email delivery test is pending.' => 'E-posta teslim testi beklemede.',
  'Email Issue' => 'E-posta Sorunu',
  'Flux Forms Email Warning:' => 'Flux Forms E-posta Uyarısı:',
