  'Checking add-on installation capabilities&hellip;' => 'Eklenti kurulum yetenekleri denetleniyor&hellip;',
  'This check runs once after plugin activation. Please refresh the page in a few moments.' => 'Bu kontrol eklenti etkinleştirildikten sonra bir kez çalışır. Lütfen birkaç dakika sonra sayfayı yenileyin.',
  'Some add-ons need a PHP server change' => 'Bazı eklentiler için PHP sunucusunda değişiklik gerekiyor',
  'Flux Forms has safely paused each affected active add-on, so the rest of the plugin can continue working.' => 'Flux Forms, etkilenen her etkin eklentiyi güvenle duraklattı; böylece eklentinin geri kalanı çalışmaya devam edebilir.',
  '(currently enabled and paused)' => '(şu anda etkin ve duraklatıldı)',
  '(not enabled)' => '(etkin değil)',
  'disabled in php.ini:' => 'php.ini içinde devre dışı:',
  'not provided by PHP or its required extension:' => 'PHP veya gerekli uzantısı tarafından sağlanmıyor:',
  'This usually means the needed PHP extension is not installed, or the function is listed in disable_functions in php.ini. Please ask your hosting provider to enable it, then refresh this page.' => 'Bu genellikle gerekli PHP uzantısının kurulu olmadığı veya işlevin php.ini içindeki disable_functions listesinde yer aldığı anlamına gelir. Lütfen barındırma sağlayıcınızdan etkinleştirmesini isteyin, ardından bu sayfayı yenileyin.',
  'If you are seeing this message, it is likely for one of these reasons: If you have a caching plugin installed, its settings may need to be reviewed.' => 'Bu mesajı görüyorsanız muhtemelen nedenlerden biri şudur: Bir önbellekleme eklentisi yüklüyse ayarlarının gözden geçirilmesi gerekebilir.',
