  'Powered by %1$sYT Form%2$s . %3$sbest Form plugin for Wordpress%4$s.' => '%1$sYT Form%2$s tarafından desteklenmektedir. %3$sWordPress için en iyi form eklentisi%4$s.',
  'Flux Forms WordPress Plugin' => 'Flux Forms WordPress Eklentisi',
  'This form requires a payment method. Please add one or change the form type.' => 'Bu form bir ödeme yöntemi gerektiriyor. Lütfen bir ödeme yöntemi ekleyin veya form türünü değiştirin.',
  'Error Monitor' => 'Hata İzleyici',
  'WordPress Core' => 'WordPress Çekirdeği',
  'Line' => 'Satır',
  'No errors detected' => 'Hata algılanmadı',
  'These errors may interfere with forms built using Flux Forms.' => 'Bu hatalar Flux Forms ile oluşturulan formları etkileyebilir.',
  'This panel is only visible to site administrators.' => 'Bu panel yalnızca site yöneticileri tarafından görülebilir.',
  'jQuery Dependency Issue' => 'jQuery Bağımlılık Sorunu',
  'jQuery is not properly loaded or available. AJAX and interactive form features may not work correctly.' => 'jQuery düzgün yüklenmemiş veya kullanılamıyor. AJAX ve etkileşimli form özellikleri düzgün çalışmayabilir.',
  'WhiteStudio.team' => 'WhiteStudio.team',
  'EFB' => 'EFB',
  'Flux Forms is a free and powerful WordPress form builder plugin for creating contact forms, payment forms, surveys, registration forms, multi-step forms, file upload forms, electronic signature forms, and audio, video, and screen recording forms, with conditional logic, email notifications, integrations, entry management, and advanced spam protection.' => 'Flux Forms; iletişim formları, ödeme formları, anketler, kayıt formları, çok adımlı formlar, dosya yükleme formları, elektronik imza formları ile ses, video ve ekran kaydı formları oluşturmak için koşullu mantık, e-posta bildirimleri, entegrasyonlar, kayıt yönetimi ve gelişmiş spam koruması sunan ücretsiz ve güçlü bir WordPress form oluşturucu eklentisidir.',
  'WordPress Form Builder Plugin' => 'WordPress Form Oluşturucu Eklentisi',
  'WordPress 5.0 or later; PHP 7.0 or later' => 'WordPress 5.0 veya üzeri; PHP 7.0 veya üzeri',
  'Flux Forms Documentation' => 'Flux Forms Dokümantasyonu',
