  'Some plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.' => 'Bazı eklenti dosyaları eksik, bu nedenle siteniz çalışmaya devam etsin diye eklenti yüklenmeyi durdurdu. Lütfen Flux Forms\'u Eklentiler sayfasından yeniden yükleyin — formlarınız, mesajlarınız ve ayarlarınız korunur.',
