  'Shortcode:' => 'Kısa kod:',
  'Run the email check' => 'E-posta kontrolünü çalıştır',
  'The last delivery check scored %s out of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Son teslimat kontrolü 100 üzerinden %s puan aldı. Mesajlarınız siteden çıkıyor, ancak çoğu posta kutusu bunları spam olarak sınıflandırıyor; bu yüzden formlarınızı dolduranlar bunları görmeyecek. Çözüm, bir SMTP hizmeti üzerinden göndermek ve alan adınız için SPF ve DKIM kayıtları eklemektir.',
  'The last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => 'Son teslimat kontrolü, mesajlarınızın siteden çıktığını ancak posta kutularının bunları spam olarak sınıflandırdığını gösterdi. Çözüm, bir SMTP hizmeti üzerinden göndermek ve alan adınız için SPF ve DKIM kayıtları eklemektir.',
  'Your form emails are going to the spam folder' => 'Form e-postalarınız spam klasörüne düşüyor',
  'Your form emails are sent, but they are not arriving' => 'Form e-postalarınız gönderiliyor ancak ulaşmıyor',
  'WordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => 'WordPress son test mesajını başarıyla gönderdi, yani siteniz ve bu eklenti üzerine düşeni yaptı — mesaj WordPress\'ten çıktıktan sonra kayboldu, gecikti veya reddedildi. Genellikle alıcı posta kutusu bunu spam saydı ya da hosting sağlayıcınız giden kuyruktan hiç teslim etmedi. Çözüm, alan adınız için SPF ve DKIM kayıtlarıyla bir SMTP hizmeti üzerinden göndermektir.',
  'WordPress cannot send your form emails' => 'WordPress form e-postalarınızı gönderemiyor',
  'The last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.' => 'Son kontrol bir mesajı posta sunucunuza bile teslim edemedi: WordPress gönderim sırasında hata bildirdi, yani siteden hiçbir şey çıkmadı. Başlamak için bir SMTP eklentisi kullanın veya hosting sağlayıcınıza PHP mail\'in devre dışı olup olmadığını sorun.',
  'Your form emails are not being delivered' => 'Form e-postalarınız teslim edilmiyor',
  'The last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.' => 'Son teslimat kontrolünde hiçbir mesaj ulaştırılamadı, yani formlarınızın gönderdiği hiçbir şey kimseye ulaşmıyor. Hosting sunucuları genellikle güvenilir bir imza olmadan e-posta gönderir; standart çözüm bir SMTP hizmeti üzerinden göndermektir.',
  'Once Weekly (Flux Forms)' => 'Haftada Bir (Flux Forms)',
  'The weekly email delivery test completed successfully.' => 'Haftalık e-posta teslimat testi başarıyla tamamlandı.',
  'The weekly email delivery test found an email delivery problem.' => 'Haftalık e-posta teslimat testi bir e-posta teslimat sorunu tespit etti.',
  'The main WordPress administrator email address is not valid.' => 'Ana WordPress yönetici e-posta adresi geçerli değil.',
  'Could not start the email delivery test.' => 'E-posta teslimat testi başlatılamadı.',
  'WordPress sent the automated test email and is waiting for it to arrive.' => 'WordPress otomatik test e-postasını gönderdi ve ulaşmasını bekliyor.',
  'WordPress could not send the automated test email. The message never left this website.' => 'WordPress otomatik test e-postasını gönderemedi. Mesaj bu web sitesinden hiç çıkmadı.',
  'The email delivery test timed out before confirmation was received.' => 'E-posta teslimat testi, onay alınamadan zaman aşımına uğradı.',
  'Weekly Flux Forms report for %s' => '%s için haftalık Flux Forms raporu',
  'Here is your weekly snapshot for %s.' => 'İşte %s için haftalık özetiniz.',
  'Report generated %s' => 'Rapor oluşturulma zamanı: %s',
  'Detailed analysis' => 'Ayrıntılı analiz',
  'Emails failed' => 'Başarısız e-postalar',
  'You can turn these reports off in Flux Forms settings.' => 'Bu raporları Flux Forms ayarlarından kapatabilirsiniz.',
  'The test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => 'Test e-postası teslim edildi, ancak teslim edilebilirlik puanı 100 üzerinden yalnızca %1$s (%2$s altında); bu nedenle formlarınızın gönderdiği e-postaların reddedilmesi veya spam olarak filtrelenmesi çok olasıdır.',
  'Run the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.' => 'Formlarınızın gönderdiği mesajların gerçekten insanlara ulaştığından emin olmak için e-posta kontrolünü çalıştırın. Kontrol, yeni WhiteStudio teslimat hizmeti üzerinden gerçek bir mesaj gönderir ve nelerin ulaştığını bildirir.',
  'Read the guide to sending email through SMTP' => 'SMTP ile e-posta gönderme kılavuzunu okuyun',
  'Delivery has not been scored yet' => 'Teslimat henüz puanlanmadı',
  'WordPress sent your email, but it never arrived' => 'WordPress e-postanızı gönderdi, ancak ulaşmadı',
  'WordPress could not send your email' => 'WordPress e-postanızı gönderemedi',
  'We could not confirm your emails are being delivered' => 'E-postalarınızın teslim edildiğini doğrulayamadık',
  'out of 100' => '100 üzerinden',
  'Your email delivery is healthy' => 'E-posta teslimatınız sağlıklı',
  'Your emails are likely going to spam' => 'E-postalarınız büyük olasılıkla spam\'e düşüyor',
  'Your emails are not reaching anybody' => 'E-postalarınız kimseye ulaşmıyor',
  'grade %s' => 'not: %s',
  'What you should do' => 'Ne yapmalısınız',
  'A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.' => 'Hosting sunucuları genellikle güvenilir bir imza olmadan e-posta gönderir; bu da form e-postalarınızı spam klasörüne düşürür veya hiç ulaşmasını engeller. Standart çözüm, bir SMTP hizmeti üzerinden göndermektir.',
  'Install an SMTP plugin and enter the details of your email service.' => 'Bir SMTP eklentisi kurun ve e-posta hizmetinizin bilgilerini girin.',
  'Add the SPF and DKIM records to your domain settings.' => 'SPF ve DKIM kayıtlarını alan adı ayarlarınıza ekleyin.',
  'Run the email check again until the score is above %s.' => 'Puan %s üzerine çıkana kadar e-posta kontrolünü tekrar çalıştırın.',
  'You have %1$s forms: %2$s active and %3$s inactive.' => 'Toplam %1$s formunuz var: %2$s aktif, %3$s pasif.',
  'Renew Flux Forms Pro' => 'Flux Forms Pro\'yu Yenile',
  'Get more from Flux Forms Pro' => 'Flux Forms Pro\'dan daha fazlasını edinin',
  'Renew your subscription to restore all Pro features and add-ons.' => 'Tüm Pro özelliklerini ve eklentileri geri getirmek için aboneliğinizi yenileyin.',
  'Unlock premium add-ons, unlimited features and priority support for your forms.' => 'Formlarınız için premium eklentilerin, sınırsız özelliklerin ve öncelikli desteğin kilidini açın.',
  'Renew Pro' => 'Pro\'yu Yenile',
  'Email delivery is working' => 'E-posta teslimatı çalışıyor',
  'The automated Flux Forms email delivery test completed successfully.' => 'Otomatik Flux Forms e-posta teslimat testi başarıyla tamamlandı.',
  'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.' => 'Buraya en fazla %1$d dosyasını ekleyebilirsiniz. Tekrar denemeden önce lütfen %2$d dakika kadar bekleyin.' . chr(0) . 'Buraya en fazla %1$d dosyası ekleyebilirsiniz. Tekrar denemeden önce lütfen %2$d dakika kadar bekleyin.',
  'This file is too large. The maximum size for this field is %s.' => 'Bu dosya çok büyük. Bu alan için izin verilen en büyük boyut %s.',
  'This file type is not accepted here. Please attach one of the file types listed on the field.' => 'Bu dosya türü burada kabul edilmiyor. Lütfen alanda listelenen dosya türlerinden birini ekleyin.',
  'This file appears to be empty. Please choose a different file.' => 'Bu dosya boş görünüyor. Lütfen farklı bir dosya seçin.',
  'The uploaded file could not be verified. Please attach it again.' => 'Yüklenen dosya doğrulanamadı. Lütfen tekrar ekleyin.',
  'X-WP-Nonce header is missing' => 'X-WP-Nonce üstbilgisi eksik',
  'Your form session has expired. Please reload the page.' => 'Form oturumunuzun süresi doldu. Lütfen sayfayı yenileyin.',
  'Form ID:' => 'Form ID:',
  'The form will be displayed on the frontend.' => 'Form ön yüzde görüntülenecektir.',
  'This link uses an older format. For improved security, new email notifications include updated links.' => 'Bu bağlantı eski bir biçim kullanıyor. Daha iyi güvenlik için yeni e-posta bildirimleri güncel bağlantılar içerir.',
  'It seems that you are the admin of this form. Please log in and try again.' => 'Bu formun yöneticisi olduğunuz görünüyor. Lütfen oturum açıp tekrar deneyin.',
  'Flux Forms couldn\'t locate the form settings. Please check your settings or contact support for assistance.' => 'Flux Forms form ayarlarını bulamadı. Lütfen ayarlarınızı kontrol edin veya yardım için destekle iletişime geçin.',
  'Y/m/d \\a\\t g:ia' => 'd.m.Y \\s\\a\\a\\t H:i',
  'Too many attempts. Please wait a few minutes and try again.' => 'Çok fazla deneme. Lütfen birkaç dakika bekleyip tekrar deneyin.',
  'The recording upload could not be verified. Please record it again and retry.' => 'Kayıt yüklemesi doğrulanamadı. Lütfen tekrar kaydedip yeniden deneyin.',
  'This recording format is not supported. Please record it again.' => 'Bu kayıt biçimi desteklenmiyor. Lütfen tekrar kaydedin.',
  'The server could not verify the recording format. Please contact the site administrator.' => 'Sunucu kayıt biçimini doğrulayamadı. Lütfen site yöneticisiyle iletişime geçin.',
  'The recording format could not be verified. Please record it again.' => 'Kayıt biçimi doğrulanamadı. Lütfen tekrar kaydedin.',
  'The server could not verify the recording duration. Please record it again and try uploading.' => 'Sunucu kayıt süresini doğrulayamadı. Lütfen tekrar kaydedip yüklemeyi deneyin.',
  'The server could not store the recording. Please try again or contact the site administrator.' => 'Sunucu kaydı depolayamadı. Lütfen tekrar deneyin veya site yöneticisiyle iletişime geçin.',
