  'The response box could not be verified. Reopen the conversation and try again.' => 'Yanıt kutusu doğrulanamadı. Konuşmayı yeniden açıp tekrar deneyin.',
  'The response attachment could not be secured. Please try again.' => 'Yanıt eki güvenli hale getirilemedi. Lütfen tekrar deneyin.',
