  'Password has been changed successfully!' => 'Parola başarıyla değiştirildi!',
  'Invalid payment selection. Please review your choices and try again. If the problem persists, contact the site administrator.' => 'Geçersiz ödeme seçimi. Lütfen seçimlerinizi gözden geçirip tekrar deneyin. Sorun devam ederse site yöneticisiyle iletişime geçin.',
  'If your emails are not being delivered, try using an SMTP plugin. For more information, %1$s click here %2$s or contact our %3$s support team %4$s.' => 'E-postalarınız teslim edilmiyorsa bir SMTP eklentisi kullanmayı deneyin. Daha fazla bilgi için %1$s buraya tıklayın %2$s veya %3$s destek ekibimizle %4$s iletişime geçin.',
