  'Built with %1$sYT Form%2$s by %3$sWhiteStudio.team%4$s' => '%3$sWhiteStudio.team%4$s tarafından %1$sYT Form%2$s ile oluşturuldu',
  'Weekly Flux Forms report' => 'Haftalık Flux Forms raporu',
  'Pro features are paused' => 'Pro özellikleri duraklatıldı',
  'Congratulations! Email System Working' => 'Tebrikler! E-posta Sistemi Çalışıyor',
  'Your server has successfully sent this test email. The email delivery system is properly configured and functioning.' => 'Sunucunuz bu test e-postasını başarıyla gönderdi. E-posta teslimat sistemi doğru yapılandırılmış ve çalışıyor.',
  'Email Delivery Tips' => 'E-posta Teslimatı İpuçları',
  'Form submitted successfully without tracking.' => 'Form izleme olmadan başarıyla gönderildi.',
  'Your message has been received and recorded successfully.' => 'Mesajınız alındı ve başarıyla kaydedildi.',
  'Reset Password' => 'Parolayı Sıfırla',
  'Or copy and paste this link:' => 'Veya şu bağlantıyı kopyalayıp yapıştırın:',
  'If you did not request this, you can safely ignore it.' => 'Bunu siz istemediyseniz bu e-postayı güvenle yok sayabilirsiniz.',
  'Hi' => 'Merhaba',
  'You have requested to reset your password.' => 'Parolanızı sıfırlamak için talepte bulundunuz.',
  'Click the button below to set a new password. This link will be valid for 24 hours.' => 'Yeni bir parola belirlemek için aşağıdaki düğmeye tıklayın. Bu bağlantı 24 saat geçerli olacaktır.',
  'Verify Email' => 'E-postayı Doğrula',
  'Your account has been successfully created!' => 'Hesabınız başarıyla oluşturuldu!',
  'Please verify your email address by clicking the button below. This activation link will be valid for 24 hours.' => 'Lütfen aşağıdaki düğmeye tıklayarak e-posta adresinizi doğrulayın. Bu etkinleştirme bağlantısı 24 saat geçerli olacaktır.',
  'A new user has registered on your website.' => 'Web sitenize yeni bir kullanıcı kaydoldu.',
  'The user has been sent a verification email to confirm their account.' => 'Kullanıcıya hesabını onaylaması için bir doğrulama e-postası gönderildi.',
  'This is an alert message regarding a SID validation error. This issue may have occurred due to a plugin conflict or an unauthorized attempt to access the website.' => 'Bu, bir SID doğrulama hatasına ilişkin bir uyarı mesajıdır. Bu sorun bir eklenti çakışmasından veya web sitesine yetkisiz erişim girişiminden kaynaklanmış olabilir.',
  'If you receive this email multiple times, it could indicate a recurring issue.' => 'Bu e-postayı birden fazla kez alırsanız, tekrarlayan bir sorun olabilir.',
  'Please contact our support team for assistance.' => 'Yardım için lütfen destek ekibimizle iletişime geçin.',
  'One or more of the plugins listed below—typically related to caching or security—might be triggering this issue. For troubleshooting, temporarily deactivate them and test your site.' => 'Aşağıda listelenen eklentilerden bir veya birkaçı—genellikle önbellek veya güvenlikle ilgili olanlar—bu soruna neden olabilir. Sorun gidermek için bunları geçici olarak devre dışı bırakın ve sitenizi test edin.',
  'SID Validation Error' => 'SID Doğrulama Hatası',
  'Please select a form to display.' => 'Görüntülenecek bir form seçin.',
  'Sürükle-bırak form oluşturucu: çok adımlı formlar, Stripe ödemeleri, koşullu mantık, dashboard, otomasyonlar ve Flux Certificates entegrasyonu. Easy Form Builder (WhiteStudio, GPL) tabanlı fork.' => 'Sürükle-bırak form oluşturucu: çok adımlı formlar, Stripe ödemeleri, koşullu mantık, dashboard, otomasyonlar ve Flux Certificates entegrasyonu. Easy Form Builder (WhiteStudio, GPL) tabanlı fork.',
  'The currency of this form is not supported.' => 'The currency of this form is not supported.',
  'The Stripe secret key is not configured.' => 'The Stripe secret key is not configured.',
  'Could not connect to Stripe: %s' => 'Could not connect to Stripe: %s',
  'Stripe API error (HTTP %d).' => 'Stripe API error (HTTP %d).',
  'Type your reply...' => 'Yanıtınızı yazın&hellip;',
  'height' => 'Yükseklik',
  'Checking email delivery...' => 'E-posta teslimi kontrol ediliyor…',
  'A test email was sent. Waiting for delivery confirmation...' => 'Test e-postası gönderildi. Teslim onayı bekleniyor…',
  'Adds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => 'Form etkinliği toplamlarınızı &ndash; formlar, görüntülemeler ve gönderimler &ndash; sitenizin ana yöneticiye gönderdiği haftalık e-postaya ekler. Bu toplamlar kendi sitenizde okunur ve asla WhiteStudio\'ya gönderilmez.',
  'A value is written to this field while another rule hides or disables it — hidden and disabled fields are not saved with the entry.' => 'Bu alana bir değer yazılıyor, başka bir kural ise onu gizliyor veya devre dışı bırakıyor &mdash; gizli ve devre dışı alanlar yanıtla birlikte kaydedilmez.',
  'Message...' => 'Mesaj&hellip;',
  'hide' => 'Gizle',
  'Uploading recording...' => 'Kayıt yükleniyor…',
  'Got it, don\'t show it again' => 'Anladım, bir daha gösterme',
  'Your text here...' => 'Metniniz burada…',
  'Waiting for the test email to arrive...' => 'Test e-postasının ulaşması bekleniyor…',
  'Still checking — please wait a moment...' => 'Hâlâ kontrol ediliyor — lütfen biraz bekleyin…',
  'Starting email delivery test...' => 'E-posta teslimat testi başlatılıyor…',
  'WordPress accepted and sent the message. Waiting for it to arrive...' => 'WordPress mesajı kabul etti ve gönderdi. Ulaşması bekleniyor…',
  'turkey' => 'Hintçe',
  'bug report' => 'Hata bildirimi',
  'kosher' => 'Koşer',
  'banner' => 'Afiş',
  'Installing add-ons...' => 'Eklentiler yükleniyor…',
  'Your forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.' => 'Formlarınıza, girdilerinize ve ayarlarınıza dokunulmadı, tüm ücretsiz özellikler çalışmaya devam ediyor ve etkinleştirme kodunuz hâlâ saklanıyor &mdash; hiçbir şey silinmedi.',
  'Open %1$sYT Form → Settings%2$s and press %1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.' => '%1$sYT Form &rarr; Ayarlar%2$s sayfasını açın ve %1$sKaydet%2$s düğmesine basın. Bu, lisansı hemen yeniden kontrol eder; bağlantı geri geldiyse Pro bir dakika içinde açılır.',
  'Still paused? Ask your hosting provider to allow outgoing HTTPS connections to %s — a firewall, proxy or regional block is the usual cause — then repeat step 1.' => 'Hâlâ duraklatılmış mı? Barındırma sağlayıcınızdan %s adresine giden HTTPS bağlantılarına izin vermesini isteyin &mdash; genellikle nedeni bir güvenlik duvarı, proxy veya bölgesel engeldir &mdash; ardından 1. adımı tekrarlayın.',
  'grace period' => 'Ek süre',
  'Your website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.' => 'Web siteniz lisans sunucusuna ulaşamadı &mdash; neredeyse her zaman barındırma tarafındaki bir ağ, güvenlik duvarı veya DNS kısıtlamasıdır.',
  'The licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.' => 'Lisans sunucusu&rsquo;nun yanıtı bozuk ulaştı; genellikle bir güvenlik eklentisi, proxy veya CDN onu yolda değiştirmiştir.',
  'Updating amount...' => 'Tutar güncelleniyor…',
  'Keys are set;%dform uses reCAPTCHA.%dforms use reCAPTCHA.' => 'Anahtarlar ayarlandı; %d formu reCAPTCHA\'yı kullanıyor. %d formda reCAPTCHA kullanılıyor.',
  'Preparing your certificate...' => 'Sertifikanız hazırlanıyor…',
  'Search elements...' => 'Eleman ara…',
  'Enter your test message here...' => 'Test mesajınızı buraya girin&hellip;',
  'Type your message here...' => 'Mesajınızı buraya yazın&hellip;',
  'Testing connection...' => 'Bağlantı test ediliyor…',
  'Saving...' => 'Kaydediliyor&hellip;',
  'Loading...' => 'Yükleniyor&hellip;',
  'To sync an<strong>existing</strong>sheet: open it in Google Sheets →<strong>Share</strong>→ paste the email above → set role to<strong>Editor</strong>. To create a<strong>new</strong>sheet, just use Form Bindings — no sharing needed.' => '<strong>Mevcut</strong> bir tabloyu senkronize etmek için: tabloyu Google E-Tablolar\'da açın &rarr; <strong>Paylaş</strong> &rarr; yukarıdaki e-postayı yapıştırın &rarr; rolü <strong>Düzenleyen</strong> yapın. <strong>Yeni</strong> bir tablo oluşturmak için Form Bağlantıları\'nı kullanmanız yeterli — paylaşım gerekmez.',
  'Go to<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a>→ Project dropdown (top-left) → New Project → name it → Create' => '<a href="https://console.cloud.google.com/" target="_blank" rel="noopener noreferrer">console.cloud.google.com</a> adresine gidin &rarr; Proje açılır menüsü (sol üst) &rarr; Yeni Proje &rarr; bir ad verin &rarr; Oluştur',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong><em>and</em><strong>Google Drive API</strong>' => 'APIs &amp; Services &rarr; Library &rarr; <strong>Google Sheets API</strong> <em>ve</em> <strong>Google Drive API</strong>\'yi etkinleştirin',
  'APIs & Services → Credentials → Create Credentials → Service Account → name it → Done' => 'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; bir ad verin &rarr; Done',
  'Open the service account → Keys tab → Add Key → Create New Key → JSON (downloads automatically)' => 'Hizmet hesabını açın &rarr; Keys sekmesi &rarr; Add Key &rarr; Create New Key &rarr; JSON (otomatik iner)',
  'Connecting service account...' => 'Hizmet hesabı bağlanıyor…',
  'tab' => 'Sekme',
  'Loading your spreadsheets...' => 'Tablolarınız yükleniyor…',
  '<strong>Use an existing sheet:</strong>open it in Google Sheets → Share → paste' => '<strong>Mevcut bir tabloyu kullanın:</strong> Google E-Tablolar\'da açın &rarr; Paylaş &rarr; şunu yapıştırın:',
  '→ Editor, then click<em>Browse My Sheets</em>again.' => '&rarr; Düzenleyen yapın, ardından <em>Tablolarıma Göz At</em>\'a tekrar tıklayın.',
  'Creating...' => 'Oluşturuluyor…',
  'Creating spreadsheet...' => 'Tablo oluşturuluyor…',
  'Loading worksheet tabs...' => 'Çalışma sayfası sekmeleri yükleniyor…',
  'Reading this form’s fields...' => 'Bu formun alanları okunuyor…',
  'Drag rows (or use ▲▼) to set the<strong>column order</strong>. Rename any<strong>header</strong>. Turn a field off to skip its column. The letter (A, B, C...) shows where each field lands.' => '<strong>Sütun sırasını</strong> belirlemek için satırları sürükleyin (veya ▲▼ kullanın). İstediğiniz <strong>başlığı</strong> yeniden adlandırın. Bir alanın sütununu atlamak için alanı kapatın. Harf (A, B, C…) her alanın nereye düştüğünü gösterir.',
  'Applying...' => 'Uygulanıyor…',
  'Open console.cloud.google.com and log in → click the Project dropdown (top-left) → New Project (or pick an existing one) → enter a name → Create' => 'console.cloud.google.com adresini açıp giriş yapın &rarr; Proje açılır menüsüne (sol üst) tıklayın &rarr; Yeni Proje (veya mevcut birini seçin) &rarr; bir ad girin &rarr; Oluştur',
  'APIs & Services → Library → enable<strong>Google Sheets API</strong>and<strong>Google Drive API</strong>(both are required — Drive lists and creates the files)' => 'APIs &amp; Services &rarr; Library &rarr; <strong>Google Sheets API</strong> ve <strong>Google Drive API</strong>\'yi etkinleştirin (ikisi de gereklidir — Drive dosyaları listeler ve oluşturur)',
  'APIs & Services → Credentials → Create Credentials → Service Account → enter a name → Done' => 'APIs &amp; Services &rarr; Credentials &rarr; Create Credentials &rarr; Service Account &rarr; bir ad girin &rarr; Done',
  'Open the service account → Keys tab → Add Key → Create New Key → choose JSON (file downloads automatically)' => 'Hizmet hesabını açın &rarr; Keys sekmesi &rarr; Add Key &rarr; Create New Key &rarr; JSON\'u seçin (dosya otomatik iner)',
  'Form Bindings → pick a form →<strong>Create New Sheet</strong>→ Save. No manual sharing needed — this is the easiest path' => 'Form Bağlantıları &rarr; bir form seçin &rarr; <strong>Yeni Tablo Oluştur</strong> &rarr; Kaydet. Elle paylaşım gerekmez — en kolay yol budur',
  '...or use an existing sheet' => '…veya mevcut bir tabloyu kullanın',
  'Prefer your own sheet? Open it → Share → paste the service account email (copy button on its card) → Editor → then Browse My Sheets in the wizard' => 'Kendi tablonuzu mu tercih ediyorsunuz? Açın &rarr; Paylaş &rarr; hizmet hesabı e-postasını yapıştırın (kartındaki kopyala düğmesi) &rarr; Düzenleyen &rarr; ardından sihirbazda Tablolarıma Göz At\'ı kullanın',
  'It must be shared with the service account’s email first: open the sheet → Share → paste the email (use the copy button on the connection card) → set Editor → Share. Then click “Browse My Sheets” again.' => 'Önce hizmet hesabının e-postasıyla paylaşılmalıdır: tabloyu açın &rarr; Paylaş &rarr; e-postayı yapıştırın (bağlantı kartındaki kopyala düğmesini kullanın) &rarr; Düzenleyen yapın &rarr; Paylaş. Ardından “Tablolarıma Göz At”a tekrar tıklayın.',
  'Open Google Cloud Console for the same project → APIs & Services → Library, and enable BOTH “Google Sheets API” and “Google Drive API”. Wait a minute, then retest.' => 'Aynı proje için Google Cloud Console\'u açın &rarr; APIs &amp; Services &rarr; Library ve HEM “Google Sheets API” HEM DE “Google Drive API”yi etkinleştirin. Bir dakika bekleyin, ardından tekrar test edin.',
  'Yes. In the binding wizard’s<strong>Columns & Fields</strong>step, drag rows (or use ▲▼) to set the order, rename each column header, and toggle any field off to skip it. The A/B/C badge shows exactly where each field lands.' => 'Evet. Bağlantı sihirbazının <strong>Sütunlar &amp; Alanlar</strong> adımında satırları sürükleyerek (veya ▲▼ kullanarak) sırayı belirleyin, her sütun başlığını yeniden adlandırın ve atlamak istediğiniz alanı kapatın. A/B/C rozeti her alanın tam olarak nereye düştüğünü gösterir.',
  'Yes. The<strong>Style & Save</strong>step offers Google-Sheets themes (colored header, frozen top row, alternating row colors). Pick one and it’s applied on the first sync, or click “Apply style now”.' => 'Evet. <strong>Stil &amp; Kaydet</strong> adımı Google E-Tablolar temaları sunar (renkli başlık, sabitlenmiş üst satır, dönüşümlü satır renkleri). Birini seçin; ilk senkronizasyonda uygulanır veya “Stili şimdi uygula”ya tıklayın.',
  'synchronized' => 'Senkronize edildi',
  '%1$s cannot run because required PHP functions are unavailable (%2$s). Ask your hosting provider to enable the required PHP extension or remove the listed functions from disabled_functions in php.ini.' => 'Gerekli PHP işlevleri kullanılamadığı için %1$s çalışamıyor (%2$s). Hosting sağlayıcınızdan gerekli PHP eklentisini etkinleştirmesini isteyin veya listelenen işlevleri php.ini içindeki disable_functions değerinden kaldırın.',
  'Checking add-on installation capabilities...' => 'Eklenti kurulum yetenekleri denetleniyor&hellip;',
  'Powered by %1$sYT Form%2$s. %3$sbest Form plugin for Wordpress%4$s.' => '%1$sYT Form%2$s tarafından desteklenmektedir. %3$sWordPress için en iyi form eklentisi%4$s.',
  'Loading forms...' => 'Formlar yükleniyor&hellip;',
